add_shortcode('fs_related_news', function($atts) {
    $current_id = get_the_ID();
    $current_type = get_post_type();

    $meta_query = ['relation' => 'OR'];
    $has_context = false;

    // 1. CONTEXT: CLUB PAGE
    if ($current_type == 'fs_club' || $current_type == 'club') {
        $has_context = true;
        $meta_query[] = ['key' => 'related_clubs', 'value' => '"' . $current_id . '"', 'compare' => 'LIKE'];
        $meta_query[] = ['key' => 'related_clubs', 'value' => $current_id, 'compare' => '='];
        $meta_query[] = ['key' => 'home_team', 'value' => '"' . $current_id . '"', 'compare' => 'LIKE'];
        $meta_query[] = ['key' => 'home_team', 'value' => $current_id, 'compare' => '='];
        $meta_query[] = ['key' => 'away_team', 'value' => '"' . $current_id . '"', 'compare' => 'LIKE'];
        $meta_query[] = ['key' => 'away_team', 'value' => $current_id, 'compare' => '='];
    } 
    // 2. CONTEXT: PLAYER PAGE
    elseif ($current_type == 'fs_player' || $current_type == 'player') {
        $has_context = true;
        $meta_query[] = ['key' => 'related_players', 'value' => '"' . $current_id . '"', 'compare' => 'LIKE'];
        $meta_query[] = ['key' => 'related_players', 'value' => $current_id, 'compare' => '='];
    } 
    // 3. CONTEXT: MATCH PAGE (Using the bulletproof ID extraction)
    elseif ($current_type == 'matches') {
        $has_context = true;

        $h_raw = get_post_meta($current_id, 'home_team', true); 
        $a_raw = get_post_meta($current_id, 'away_team', true);

        // Safely extract Home ID
        $h_id = 0; 
        if (is_numeric($h_raw)) { $h_id = $h_raw; } 
        elseif (is_array($h_raw)) { $h_id = $h_raw[0]; }
        elseif (is_string($h_raw)) { 
            preg_match('/"(\d+)"/', $h_raw, $m_h);
            if(isset($m_h[1])) $h_id = $m_h[1];
        }

        // Safely extract Away ID
        $a_id = 0;
        if (is_numeric($a_raw)) { $a_id = $a_raw; } 
        elseif (is_array($a_raw)) { $a_id = $a_raw[0]; }
        elseif (is_string($a_raw)) { 
            preg_match('/"(\d+)"/', $a_raw, $m_a);
            if(isset($m_a[1])) $a_id = $m_a[1];
        }

        // Build the query for whatever teams we found
        $teams_playing = array_filter([$h_id, $a_id]);
        foreach ($teams_playing as $tid) {
            // Standard News
            $meta_query[] = ['key' => 'related_clubs', 'value' => '"' . $tid . '"', 'compare' => 'LIKE'];
            $meta_query[] = ['key' => 'related_clubs', 'value' => $tid, 'compare' => '='];
            // Other Match Reports
            $meta_query[] = ['key' => 'home_team', 'value' => '"' . $tid . '"', 'compare' => 'LIKE'];
            $meta_query[] = ['key' => 'home_team', 'value' => $tid, 'compare' => '='];
            $meta_query[] = ['key' => 'away_team', 'value' => '"' . $tid . '"', 'compare' => 'LIKE'];
            $meta_query[] = ['key' => 'away_team', 'value' => $tid, 'compare' => '='];
        }
    }

    // 4. BASE QUERY BUILDER
    $args = [
        'post_type'      => ['post', 'matches'], 
        'posts_per_page' => 6,
        'orderby'        => 'date',
        'order'          => 'DESC',
        'post__not_in'   => [$current_id], // Don't show the current match on its own page
    ];

    if ($has_context) {
        $meta_query[] = ['key' => 'is_league_wide', 'value' => '1', 'compare' => '='];
        $args['meta_query'] = $meta_query;
    }

    $query = new WP_Query($args);

    if (!$query->have_posts()) {
        $title_fallback = $has_context ? get_the_title() : 'the league';
        return '<p style="color:#999; font-size:12px; font-style:italic; padding:10px; border-bottom:1px solid #eee;">No recent news or reports available for '.$title_fallback.'.</p>';
    }

    // 5. OUTPUT
    $output = '<div class="fs-news-feed">';
    $output .= '<h4 style="font-family:\'Playfair Display\', serif; border-bottom:2px solid #0A3B25; padding-bottom:5px; margin-bottom:15px; color:#1a1a1a;">Latest News & Reports</h4>';

    foreach ($query->posts as $post) {
        $link  = get_permalink($post->ID);
        $title = get_the_title($post->ID);
        $date  = get_the_date('d M Y', $post->ID);
        $img   = get_the_post_thumbnail_url($post->ID, 'thumbnail'); 
        $ptype = $post->post_type;

        $label = '';
        if ($ptype === 'matches') {
            $h_score = get_field('home_score', $post->ID);
            if ($h_score !== '' && $h_score !== null) {
                $label = '<span style="background:#0e3622; color:#fff; font-size:9px; padding:2px 4px; border-radius:3px; margin-right:5px; font-weight:bold;">REPORT</span>';
            } else {
                $label = '<span style="background:#d93025; color:#fff; font-size:9px; padding:2px 4px; border-radius:3px; margin-right:5px; font-weight:bold;">PREVIEW</span>';
            }
        } else {
            $is_global = get_field('is_league_wide', $post->ID);
            if ($is_global) {
                $label = '<span style="background:#1a1a1a; color:#fff; font-size:9px; padding:2px 4px; border-radius:3px; margin-right:5px; font-weight:bold;">LEAGUE</span>';
            } else {
                $label = '<span style="background:#0A3B25; color:#fff; font-size:9px; padding:2px 4px; border-radius:3px; margin-right:5px; font-weight:bold;">NEWS</span>';
            }
        }

        $output .= '<div style="display:flex; gap:15px; margin-bottom:15px; border-bottom:1px solid #eee; padding-bottom:15px;">';

        if ($img) {
            $output .= '<a href="'.$link.'" style="flex-shrink:0;">';
            $output .= '<img src="'.$img.'" style="width:80px; height:60px; object-fit:cover; border-radius:4px;">';
            $output .= '</a>';
        }

        $output .= '<div>';
        $output .= '<div style="font-size:10px; color:#888; text-transform:uppercase; margin-bottom:3px; display:flex; align-items:center;">'.$label . ' <span style="margin-left:5px;">' . $date . '</span></div>';
        $output .= '<a href="'.$link.'" style="text-decoration:none; color:#1a1a1a; font-weight:bold; font-size:14px; line-height:1.3; display:block;">'.$title.'</a>';
        $output .= '</div>';

        $output .= '</div>';
    }

    $output .= '</div>';
    wp_reset_postdata();

    return $output;
});

