add_shortcode('fs_tour_page', function() {
    $tid = get_the_ID();

    // Grab the ACF Fields
    $destination = get_field('tour_destination', $tid);
    $dates = get_field('tour_dates', $tid);
    $price = get_field('price_thb', $tid);
    $raw_tier = get_field('tour_tier', $tid);
    $min_guests = get_field('minimum_guests_required_', $tid); 
    $inclusions = get_field('inclusions', $tid) ?: [];
    $itinerary = get_field('tour_itinerary', $tid);

    // Grab the Matches
    $match_1 = get_field('match_week', $tid);
    $match_2 = get_field('match_week_2', $tid); 

    // Grab the Featured Image
    $bg_img = get_the_post_thumbnail_url($tid, 'full');

    // Translate the operational backend tier to a premium front-end label
    $display_tier = '';
    switch ($raw_tier) {
        case 'Domestic (Single)': $display_tier = 'Matchday Experience'; break;
        case 'Domestic (Double)': $display_tier = 'Thai Football Weekender'; break;
        case 'Summer Series (Single)': $display_tier = 'Summer Series Matchday'; break;
        case 'Summer Series (Double)': $display_tier = 'Summer Series Weekender'; break;
        default: $display_tier = $raw_tier; break; // Fallback
    }

    // Helper function to build a fixture card
    $build_fixture_card = function($m_raw) {
        if (!$m_raw) return '';
        $m_id = is_array($m_raw) ? $m_raw[0] : (is_object($m_raw) ? $m_raw->ID : $m_raw);

        $h_team = get_field('home_team', $m_id);
        $a_team = get_field('away_team', $m_id);
        $h_id = is_array($h_team) ? $h_team[0] : $h_team;
        $a_id = is_array($a_team) ? $a_team[0] : $a_team;

        $h_name = get_the_title($h_id);
        $a_name = get_the_title($a_id);
        $h_logo = get_the_post_thumbnail_url($h_id, 'thumbnail');
        $a_logo = get_the_post_thumbnail_url($a_id, 'thumbnail');

        return '
        <div style="background:#f4f8f6; border:1px solid #d1e2d9; padding:15px; border-radius:4px; margin-bottom:15px; display:flex; align-items:center; justify-content:center; gap:20px;">
            <div style="text-align:right; flex:1; font-weight:bold; font-family:\'Lato\', sans-serif;">'.$h_name.'</div>
            <img src="'.$h_logo.'" style="width:40px; height:40px; object-fit:contain;">
            <div style="font-weight:900; color:#0e3622;">VS</div>
            <img src="'.$a_logo.'" style="width:40px; height:40px; object-fit:contain;">
            <div style="text-align:left; flex:1; font-weight:bold; font-family:\'Lato\', sans-serif;">'.$a_name.'</div>
        </div>';
    };

    // Determine the header background style (Image with gradient overlay, or solid color fallback)
    $header_style = "background: #0e3622;";
    if ($bg_img) {
        $header_style = "background: linear-gradient(rgba(14,54,34,0.7), rgba(14,54,34,0.85)), url('{$bg_img}'); background-size: cover; background-position: center;";
    }

    ob_start();
    ?>
    <style>
        .fs-tour-wrap { font-family: 'Lato', sans-serif; color: #1a1a1a; }
        .fs-tour-header { padding: 60px 30px; border-radius: 4px 4px 0 0; text-align: center; }
        .fs-tour-tier { font-size: 11px; text-transform: uppercase; letter-spacing: 2px; color: #a3c9b3; margin-bottom: 10px; font-weight: bold; }
        .fs-tour-title { font-family: 'Playfair Display', serif; font-size: 42px; font-weight: 900; margin: 0 0 10px 0; text-transform: uppercase; color: #ffffff !important; line-height: 1.1; }
        .fs-tour-dates { font-size: 16px; font-weight: bold; color: #ffffff !important; }

        .fs-tour-body { border: 1px solid #eeeeee; border-top: none; padding: 30px; background: #fff; border-radius: 0 0 4px 4px; display: flex; gap: 40px; flex-wrap: wrap; }
        .fs-tour-main { flex: 2; min-width: 300px; }
        .fs-tour-sidebar { flex: 1; min-width: 250px; background: #fdfdfd; padding: 25px; border: 1px solid #eee; border-radius: 4px; height: fit-content; }
        .fs-section-title { font-family: 'Playfair Display', serif; font-size: 22px; font-weight: 900; margin-bottom: 20px; color: #0e3622; border-bottom: 2px solid #0e3622; padding-bottom: 10px; }
        .fs-inclusion-list { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-bottom: 30px; }
        .fs-inclusion-list li { display: flex; align-items: flex-start; gap: 10px; font-size: 14px; }
        .fs-check { color: #0e3622; font-weight: bold; }
        .fs-price-block { text-align: center; margin-bottom: 20px; }
        .fs-price { font-size: 42px; font-weight: 900; color: #0e3622; font-family: 'Playfair Display', serif; line-height: 1; }
        .fs-price-sub { font-size: 12px; color: #888; text-transform: uppercase; margin-top: 5px; }
        .fs-book-btn { display: block; background: #0e3622; color: #fff !important; text-align: center; padding: 15px; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; text-decoration: none; border-radius: 4px; transition: 0.2s; }
        .fs-book-btn:hover { background: #0a2919; }

        @media (max-width: 768px) {
            .fs-inclusion-list { grid-template-columns: 1fr; }
            .fs-tour-body { flex-direction: column; padding: 20px; }
            .fs-tour-title { font-size: 32px; }
            .fs-tour-header { padding: 40px 20px; }
        }
    </style>

    <div class="fs-tour-wrap">
        <div class="fs-tour-header" style="<?php echo $header_style; ?>">
            <div class="fs-tour-tier"><?php echo esc_html($display_tier); ?></div>
            <h1 class="fs-tour-title"><?php echo esc_html($destination); ?></h1>
            <div class="fs-tour-dates">🗓️ <?php echo esc_html($dates); ?></div>
        </div>

        <div class="fs-tour-body">

            <div class="fs-tour-main">
                <h2 class="fs-section-title">The Fixtures</h2>
                <?php 
                    echo $build_fixture_card($match_1); 
                    echo $build_fixture_card($match_2);
                ?>

                <h2 class="fs-section-title" style="margin-top:40px;">What's Included</h2>
                <ul class="fs-inclusion-list">
                    <?php foreach($inclusions as $inc): ?>
                        <li><span class="fs-check">✓</span> <?php echo esc_html($inc); ?></li>
                    <?php endforeach; ?>
                </ul>

                <h2 class="fs-section-title">The Itinerary</h2>
                <div style="line-height:1.6; color:#444;">
                    <?php echo $itinerary; ?>
                </div>
            </div>

            <div class="fs-tour-sidebar">
                <div class="fs-price-block">
                    <div class="fs-price">฿<?php echo number_format((float)$price); ?></div>
                    <div class="fs-price-sub">Per Person</div>
                </div>

                <?php if($min_guests): ?>
                    <div style="text-align:center; font-size:12px; color:#666; margin-bottom:20px; padding:10px; background:#f9f9f9; border:1px dashed #ccc;">
                        Minimum <?php echo $min_guests; ?> guests required for tour to proceed.
                    </div>
                <?php endif; ?>

                <a href="mailto:caustonsimon.com?subject=Tour Inquiry: <?php echo esc_attr($destination); ?>" class="fs-book-btn">Register Interest</a>
            </div>

        </div>
    </div>
    <?php
    return ob_get_clean();
});

