add_filter('the_content', function($content) {
    if (is_singular('matches') && in_the_loop() && is_main_query()) {

        $match_id = get_the_ID();

        // 1. Generate the dynamic banners
        $graphic_banner = '<div style="margin: 30px 0;">' . do_shortcode('[fs_match_report_graphic id="' . $match_id . '"]') . '</div>';
        $cta_banner = '<div style="margin-top: 50px; border-top: 1px solid #eee; padding-top: 10px;">' . do_shortcode('[fs_tour_cta]') . '</div>';

        // 2. Look for your new quick placeholder tag
        $placeholder = '[IG]';

        if (strpos($content, $placeholder) !== false) {
            // Swap [IG] for the graphic
            $content = str_replace($placeholder, $graphic_banner, $content);
        } else {
            // Fallback: If [IG] isn't typed, put it at the top
            $content = $graphic_banner . $content;
        }

        // 3. Always glue the Tour CTA to the very bottom
        $content = $content . $cta_banner;
    }

    return $content;
});

