add_shortcode('fs_8_wonders', function($atts) {
    $post_id = get_the_ID();

    // 1. HELPER FUNCTION TO GET IDs SAFELY
    $get_safe_id = function($field) {
        if (!$field) return 0;
        if (is_numeric($field)) return intval($field);
        if (is_object($field) && isset($field->ID)) return intval($field->ID);
        if (is_array($field) && isset($field[0])) {
            return is_object($field[0]) ? intval($field[0]->ID) : intval($field[0]);
        }
        return 0;
    };

    // 2. FETCH TEXT FIELDS
    $kick_off_text = get_field('kick_off_text', $post_id);
    $deep_dive_text = get_field('deep_dive_analysis', $post_id);
    $final_whistle_text = get_field('final_whistle_text', $post_id);

    // 3. FETCH MATCH WEEK
    $week = intval(get_field('match_week', $post_id));
    if (!$week && isset($atts['week'])) $week = intval($atts['week']);
    if (!$week) return '<p style="text-align:center; padding: 20px;">Please specify a match week.</p>';

    // 4. FETCH DEEP DIVE MATCH ID
    $dd_match_id = $get_safe_id(get_field('deep_dive_match', $post_id));

    // 5. FETCH & CLEAN EXCLUDED MATCHES
    $exclude_arr = [];
    $acf_excludes = get_field('excluded_matches', $post_id);

    if ($acf_excludes) {
        if (!is_array($acf_excludes)) $acf_excludes = [$acf_excludes];
        foreach ($acf_excludes as $ep) {
            $clean_id = $get_safe_id($ep);
            if ($clean_id > 0) $exclude_arr[] = $clean_id;
        }
    }

    $main_loop_excludes = $exclude_arr;
    if ($dd_match_id > 0) {
        $main_loop_excludes[] = $dd_match_id;
    }
    $main_loop_excludes = array_values(array_unique(array_filter($main_loop_excludes))); 

    // 6. COMPACT MATCH RENDERER
    $wrap_class = 'fs-8w-ind-' . uniqid();
    $render_match_graphic = function($m_id) use ($get_safe_id, $wrap_class) {
        $h_id = $get_safe_id(get_field('home_team', $m_id));
        $a_id = $get_safe_id(get_field('away_team', $m_id));

        $h_logo = get_the_post_thumbnail_url($h_id, 'full') ?: get_the_post_thumbnail_url($h_id, 'thumbnail');
        $a_logo = get_the_post_thumbnail_url($a_id, 'full') ?: get_the_post_thumbnail_url($a_id, 'thumbnail');

        $h_color = get_field('primary_colour', $h_id) ?: '#e60000';
        $a_color = get_field('primary_colour', $a_id) ?: '#0033cc';

        $h_score = get_field('home_score', $m_id) !== '' ? get_field('home_score', $m_id) : '-';
        $a_score = get_field('away_score', $m_id) !== '' ? get_field('away_score', $m_id) : '-';
        $h_xg = get_field('home_xg', $m_id) ?: '0.00';
        $a_xg = get_field('away_xg', $m_id) ?: '0.00';

        $home_scorers_html = '';
        $away_scorers_html = '';
        for ($i = 1; $i <= 15; $i++) {
            $scorer = get_field('goal_' . $i . '_player', $m_id);
            $g_min = get_field('goal_' . $i . '_minute', $m_id);
            if ($scorer) {
                $pid = $get_safe_id($scorer);
                $p_club_id = $get_safe_id(get_field('current_club', $pid));

                $is_og = false;
                $g_min_display = '';
                if ($g_min) {
                    $m_clean = trim(str_replace("'", "", $g_min)); 
                    if (stripos($m_clean, 'og') !== false) {
                        $is_og = true; $g_min_display = " ({$m_clean})"; 
                    } else {
                        $g_min_display = " ({$m_clean}')"; 
                    }
                }

                $scorer_line = '<div>⚽ ' . get_the_title($pid) . $g_min_display . '</div>';

                if ($p_club_id === $h_id) {
                    if ($is_og) $away_scorers_html .= $scorer_line; else $home_scorers_html .= $scorer_line; 
                } elseif ($p_club_id === $a_id) {
                    if ($is_og) $home_scorers_html .= $scorer_line; else $away_scorers_html .= $scorer_line; 
                }
            }
        }

        $h_poss_val = get_field('home_posession', $m_id) !== '' ? get_field('home_posession', $m_id) : get_field('home_possession', $m_id);
        $h_poss = ($h_poss_val !== '' && $h_poss_val !== false && $h_poss_val !== null) ? intval($h_poss_val) : 50;
        $a_poss = 100 - $h_poss;

        $m_out = '<div class="fs-compact-mg">';
            $m_out .= '<div class="fs-header">';
                $m_out .= '<div class="fs-team">';
