                $m_out .= '</div>';
                $m_out .= '<div class="fs-score">' . $h_score . ' - ' . $a_score . '</div>';
                $m_out .= '<div class="fs-team away">';
                    if($a_logo) $m_out .= '<div class="fs-logo-wrap"><img class="fs-logo" src="'.$a_logo.'"></div>';
                    $m_out .= '<div class="fs-name-wrap"><div class="fs-team-name" style="color:'.$a_color.';">' . get_the_title($a_id) . '</div><div style="font-size:11px; color:#888; margin-top:4px; font-weight:bold;">XG '.$a_xg.'</div><div class="fs-scorers">' . $away_scorers_html . '</div></div>';
                $m_out .= '</div>';
            $m_out .= '</div>';

            $m_out .= '<div class="fs-stats">';
                $m_out .= '<div class="fs-wheel-col">';
                    $m_out .= '<div style="font-size:11px; text-transform:uppercase; color:#777; font-weight:bold; margin-bottom:15px;">Possession</div>';
                    $m_out .= '<div style="position:relative; width:100px; height:100px; margin:0 auto;">';
                        $dash_h = max(0, $h_poss - 1.5);
