                            $m_out .= '</div>';
                        $m_out .= '</div>';
                    }
                $m_out .= '</div>'; 
            $m_out .= '</div>'; 
        $m_out .= '</div>'; 

        $summary = get_field('newsletter_summary', $m_id); 
