            .' . $wrap_class . ' .fs-bars-col { width: 100%; }
        }
    </style>';

    $out .= '<div class="' . $wrap_class . '">';

    // A. THE KICK OFF TEXT
    if ($kick_off_text) {
        $out .= '<div style="margin-bottom: 50px;">';
        $out .= '<h2 class="fs-section-title">The Kick Off</h2>';
        $out .= wpautop($kick_off_text);
        $out .= '</div>';
    }

    // B. THE MAIN MATCHES LOOP 
    $args = [
        'post_type'      => 'matches', 
        'posts_per_page' => 8,
        'tax_query'      => [['taxonomy' => 'league', 'field' => 'slug', 'terms' => 't1']],
        'meta_query'     => ['relation' => 'AND', ['key' => 'match_week', 'value' => $week, 'compare' => '='], ['key' => 'competition', 'value' => 'Thai League 1', 'compare' => '=']],
        'order'          => 'ASC',
        'post__not'      => $main_loop_excludes
    ];

    $query = new WP_Query($args);
    if ($query->have_posts()) {
        while ($query->have_posts()) {
            $query->the_post();
            $current_match_id = get_the_ID();

            // THE BRUTE FORCE EXCLUSION WALL
            if (in_array($current_match_id, $main_loop_excludes)) {
                continue; 
            }

            $out .= $render_match_graphic($current_match_id);
        }
        wp_reset_postdata();
    }

    // C. THE DEEP DIVE SECTION
    if ($deep_dive_text || $dd_match_id) {
        $out .= '<div style="margin-top: 60px; padding-top: 40px; border-top: 4px solid #111;">';
        $out .= '<h2 class="fs-section-title">The Deep Dive</h2>';

        if ($deep_dive_text) {
            $out .= '<div style="margin-bottom: 30px;">' . wpautop($deep_dive_text) . '</div>';
        }

        if ($dd_match_id) {
            global $post;
            $original_post = $post;
            $post = get_post($dd_match_id);
            setup_postdata($post);

            $out .= do_shortcode('[fs_match_report_graphic]'); 

            $post = $original_post;
            wp_reset_postdata();
        }
        $out .= '</div>';
    }

    // D. THE FINAL WHISTLE SECTION
    if ($final_whistle_text) {
        $out .= '<div style="margin-top: 50px; padding-top: 40px; border-top: 2px solid #ccc;">';
        $out .= '<h2 class="fs-section-title" style="font-size: 24px;">The Final Whistle</h2>';
        $out .= '<div>' . wpautop($final_whistle_text) . '</div>';
        $out .= '</div>';
    }

    $out .= '</div>';
    return $out;
});

