add_shortcode('fs_club_hub', 'fs_render_club_dropdown_taxonomy');

function fs_render_club_dropdown_taxonomy($atts) {
    $atts = shortcode_atts(['mode' => 'standard'], $atts);
    $is_header = ($atts['mode'] === 'header');
    $taxonomy = 'league'; 

    $clubs = get_posts([
        'post_type'   => 'club',
        'numberposts' => -1,
        'orderby'     => 'title',
        'order'       => 'ASC'
    ]);

    if (empty($clubs)) {
        return '<p style="text-align:center; color:#888; font-family:\'Lato\', sans-serif; font-size:12px;">Updating...</p>';
    }

    $grouped_clubs = [];
    $allowed_leagues = ['t1', 't2', 'thai league 1', 'thai league 2'];

    foreach ($clubs as $club) {
        $terms = get_the_terms($club->ID, $taxonomy);
        if ($terms && !is_wp_error($terms)) {
            $term_name = $terms[0]->name;
            if (in_array(strtolower($term_name), $allowed_leagues)) {
                $grouped_clubs[$term_name][] = $club;
            }
        }
    }

    ksort($grouped_clubs);

    if ($is_header) {
        $output = '<div class="fs-club-dropdown-wrap" style="width: 100%; max-width: 220px; float: right; margin-top: 8px;">';
        $output .= '<select id="fs-club-select-header" onchange="if(this.value) window.location.href=this.value;" style="width: 100%; padding: 8px 12px; font-family: \'Lato\', sans-serif; font-size: 13px; font-weight: bold; color: #0A3B25; border: 2px solid #0A3B25; border-radius: 4px; background-color: #ffffff; cursor: pointer; outline: none; appearance: auto;">';
        $output .= '<option value="" style="color:#1a1a1a;">Select Club...</option>';
    } else {
        $output = '<div class="fs-club-dropdown-wrap" style="max-width: 400px; margin: 0 auto 30px auto; text-align: center;">';
        $output .= '<label for="fs-club-select" style="display: block; font-family: \'Playfair Display\', Georgia, serif; font-size: 22px; font-weight: 900; color: #0A3B25; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 1px;">Select a Club</label>';
        $output .= '<select id="fs-club-select" onchange="if(this.value) window.location.href=this.value;" style="width: 100%; padding: 14px 18px; font-family: \'Lato\', sans-serif; font-size: 16px; font-weight: bold; color: #1a1a1a; border: 2px solid #0A3B25; border-radius: 4px; background-color: #ffffff; cursor: pointer; box-shadow: 0 4px 6px rgba(0,0,0,0.05); appearance: auto; outline: none;">';
        $output .= '<option value="">-- Choose a Team --</option>';
    }

    foreach ($grouped_clubs as $term_name => $club_list) {
        $display_label = $term_name;
        if (strtoupper($term_name) === 'T1') {
            $display_label = 'Thai League 1';
        } elseif (strtoupper($term_name) === 'T2') {
            $display_label = 'Thai League 2';
        }

        $output .= '<optgroup label="' . esc_attr($display_label) . '" style="font-weight: 900; color: #0A3B25; font-style: normal;">';
        foreach ($club_list as $club) {
            $output .= '<option value="' . esc_url(get_permalink($club->ID)) . '" style="font-weight: normal; color: #1a1a1a;">' . esc_html($club->post_title) . '</option>';
        }
        $output .= '</optgroup>';
    }

    $output .= '</select>';
    $output .= '</div>';

    if ($is_header) {
        $output .= '<div style="clear: both;"></div>';
    }

    return $output;
}

