add_shortcode('fs_fast_sync', 'fs_render_fast_sync_tool');

function fs_render_fast_sync_tool() {
    if (!current_user_can('edit_posts')) {
        return ''; 
    }

    $args = [
        'post_type'   => 'club',
        'numberposts' => -1,
        'orderby'     => 'title',
        'order'       => 'ASC',
        'meta_query'  => [
            'relation' => 'OR',
            ['key' => 'footystats_id', 'compare' => 'NOT EXISTS'],
            ['key' => 'footystats_id', 'value' => '', 'compare' => '='],
            ['key' => 'footystats_id', 'value' => '0', 'compare' => '=']
        ]
    ];

    $clubs = get_posts($args);

    if (empty($clubs)) {
        return '<h3 style="text-align:center; color:#0A3B25; font-family:\'Playfair Display\', serif;">✅ ALL CLUBS SUCCESSFULLY SYNCED</h3>';
    }

    // Group the unsynced clubs by their league taxonomy
    $grouped_clubs = [];
    foreach ($clubs as $club) {
        $terms = get_the_terms($club->ID, 'league');
        $term_name = ($terms && !is_wp_error($terms)) ? $terms[0]->name : 'Unassigned';
        $grouped_clubs[$term_name][] = $club;
    }

    // Sort the regions alphabetically
    ksort($grouped_clubs);

    $html = '<div id="fs-sync-container" style="max-width: 600px; margin: 0 auto; font-family: \'Lato\', sans-serif;">';
    $html .= '<h3 style="text-align:center; color:#0A3B25; font-family:\'Playfair Display\', serif;">⚠️ UNSYNCED CLUBS (' . count($clubs) . ' REMAINING)</h3>';

    $html .= '<table style="width:100%; border-collapse: collapse; margin-top: 20px; background: #fff; box-shadow: 0 4px 6px rgba(0,0,0,0.05);">';

    // Loop through each league group and render a section header
    foreach ($grouped_clubs as $league_name => $club_list) {
        $html .= '<tr style="background-color: #0A3B25; color: #fff;">';
        $html .= '<th colspan="3" style="padding: 10px 15px; text-align: left; text-transform: uppercase; font-size: 14px; font-family: \'Playfair Display\', serif;">' . esc_html($league_name) . ' (' . count($club_list) . ')</th>';
        $html .= '</tr>';

        // Render the clubs inside this league
        foreach ($club_list as $club) {
            $html .= '<tr id="sync-row-' . $club->ID . '" style="border-bottom: 1px solid #eee;">';

            $html .= '<td style="padding: 12px 15px; font-weight: bold; color: #1a1a1a; font-size: 15px;">' . esc_html($club->post_title) . '</td>';

            $html .= '<td style="padding: 12px 15px; width: 140px;">';
            $html .= '<input type="number" id="fs-id-' . $club->ID . '" placeholder="FootyStats ID" style="width: 100%; padding: 8px; border: 2px solid #ccc; border-radius: 4px; outline: none;">';
            $html .= '</td>';

            $html .= '<td style="padding: 12px 15px; width: 90px; text-align: right;">';
            $html .= '<button onclick="fs_sync_club(' . $club->ID . ')" style="background: #0A3B25; color: #fff; border: none; padding: 8px 16px; border-radius: 4px; cursor: pointer; font-weight: bold; width: 100%;">Save</button>';
            $html .= '</td>';

            $html .= '</tr>';
        }
    }

    $html .= '</table></div>';

    $ajax_url = admin_url('admin-ajax.php');
    $html .= "
    <script>
    function fs_sync_club(clubId) {
        let inputField = document.getElementById('fs-id-' + clubId);
        let fsId = inputField.value.trim();
        let btn = document.querySelector('#sync-row-' + clubId + ' button');

        if(!fsId) { 
            inputField.style.borderColor = 'red';
            return; 
        }

        btn.innerText = '...';
        btn.style.opacity = '0.7';

        let data = new FormData();
        data.append('action', 'fs_quick_sync_save');
        data.append('club_id', clubId);
        data.append('fs_id', fsId);

        fetch('{$ajax_url}', {
            method: 'POST',
            body: data
        })
        .then(res => res.json())
        .then(res => {
            if(res.success) {
                let row = document.getElementById('sync-row-' + clubId);
                row.style.transition = 'all 0.3s ease';
                row.style.opacity = '0';
                setTimeout(() => row.style.display = 'none', 300);
            } else {
                alert('Database Error: Could not save ID.');
                btn.innerText = 'Save';
                btn.style.opacity = '1';
            }
        });
    }
    </script>
    ";

    return $html;
}

// =========================================================================
// 3. AJAX HANDLER FOR FAST-SYNC SAVING
// =========================================================================
add_action('wp_ajax_fs_quick_sync_save', 'fs_ajax_quick_sync_save');

function fs_ajax_quick_sync_save() {
    if (!current_user_can('edit_posts')) {
        wp_send_json_error('Unauthorized');
    }

    $club_id = intval($_POST['club_id']);
    $fs_id = sanitize_text_field($_POST['fs_id']);

    if ($club_id && $fs_id) {
        update_field('footystats_id', $fs_id, $club_id); 
        wp_send_json_success('Saved');
    }

    wp_send_json_error('Missing data');
}

