add_shortcode('fs_match_report_graphic', function($atts) {
    $match_id = isset($atts['id']) ? intval($atts['id']) : get_the_ID();

    // SAFE ID EXTRACTOR
    $get_safe_id = function($field) {
        if (!$field) return 0;
        if (is_object($field)) return $field->ID;
        if (is_array($field)) return is_object($field[0]) ? $field[0]->ID : intval($field[0]);
        return intval($field);
    };

    // 1. UNPACK THE MASTER JSON (For Lineups & Events)
    $raw_data = get_field('raw_match_data', $match_id, false); 
    $data = [];

    if (!empty($raw_data)) {
        $decoded = base64_decode(trim($raw_data));
        if ($decoded && is_array(json_decode($decoded, true))) {
            $data = json_decode($decoded, true);
        } else {
            $fallback = json_decode(trim($raw_data), true);
            if (is_array($fallback)) {
                $data = $fallback;
            }
        }
    }

    // SAFE STAT EXTRACTOR (Handles Ints and Floats for xG)
    $get_stat = function($key, $is_float = false) use ($match_id, $data) {
        $val = get_field($key, $match_id);
        if ($val !== false && $val !== null && $val !== '') {
            return $is_float ? (float)$val : (int)$val;
        }
        if (isset($data[$key]) && $data[$key] !== '') {
            return $is_float ? (float)$data[$key] : (int)$data[$key];
        }
        return $is_float ? null : 0;
    };

    // 2. HEADER DATA & STATUS CHECK
    $h_id = $get_safe_id(get_field('home_team', $match_id));
    $a_id = $get_safe_id(get_field('away_team', $match_id));

    $h_link = get_permalink($h_id);
    $a_link = get_permalink($a_id);

    $h_logo = get_field('club_logo_url', $h_id) ?: get_the_post_thumbnail_url($h_id, 'thumbnail');
    $a_logo = get_field('club_logo_url', $a_id) ?: get_the_post_thumbnail_url($a_id, 'thumbnail');

    $raw_h_color = get_field('primary_colour', $h_id) ?: '#e60000';
    $raw_a_color = get_field('primary_colour', $a_id) ?: '#0033cc';
    $h_color = (in_array(strtolower(trim($raw_h_color)), ['#ffffff', '#fff', 'white'])) ? '#111111' : $raw_h_color;
    $a_color = (in_array(strtolower(trim($raw_a_color)), ['#ffffff', '#fff', 'white'])) ? '#111111' : $raw_a_color;

    $raw_h_score = get_field('home_score', $match_id);
    $raw_a_score = get_field('away_score', $match_id);

    // INTELLIGENCE: Is this an unplayed fixture or a finished result?
    $is_fixture = ($raw_h_score === '' || $raw_h_score === null);

    $h_score = !$is_fixture ? $raw_h_score : '-';
    $a_score = !$is_fixture ? $raw_a_score : '-';

    $h_xg = $get_stat('home_xg', true);
    $a_xg = $get_stat('away_xg', true);
    $h_xg_disp = ($h_xg !== null) ? number_format($h_xg, 2) : null;
    $a_xg_disp = ($a_xg !== null) ? number_format($a_xg, 2) : null;

    $h_formation = $data['home_formation'] ?? '';
    $a_formation = $data['away_formation'] ?? '';
    $motm = get_field('man_of_the_match', $match_id);

    // DATE & TIME LOGIC
    $match_date_raw = get_field('date', $match_id);
    $ts = $match_date_raw ? strtotime((string)$match_date_raw) : false;
    $display_date = ($ts && $ts > 100000) ? date('l, d F Y', $ts) : ($match_date_raw ?: 'Date TBC');

    $raw_time = get_field('kick_off_time', $match_id);
    $kick_off = ($raw_time && $raw_time !== '00:00:00' && $raw_time !== '00:00') ? date('H:i', strtotime($raw_time)) : 'TBC';

    // 3. EVENTS (Scorers, Assists, Subs, Cards)
    $events_map = [];
    $home_scorers_html = '';
    $away_scorers_html = '';

    if (!$is_fixture && !empty($data['match_events'])) {
        foreach ($data['match_events'] as $row) {
            $type = strtolower(trim($row['event_type'] ?? ''));
            $detail = strtolower(trim($row['event_detail'] ?? ''));
            $min = $row['event_minute'] ?? 0;
            $p1_id = $row['p1_id'] ?? 0;
            $p2_id = $row['p2_id'] ?? 0; 
            $p1_name = $row['p1_name'] ?? 'Unknown';
            $p2_name = $row['p2_name'] ?? null;
            $team = $row['event_team'] ?? 'Home';

            $is_og = (strpos($detail, 'own') !== false);
            $is_pen = (strpos($detail, 'penalty') !== false);

            if ($type === 'goal' && strpos($detail, 'missed') === false) {
                if ($p1_id) $events_map[$p1_id]['goals'][] = $min;
                $lbl = '<span style="color:#888; font-size:11px; font-weight:normal;">(' . $min . "'" . ($is_og ? ' OG' : '') . ($is_pen ? ' pen' : '') . ')</span>';
                $p1_html = $p1_id ? '<a href="'.esc_url(get_permalink($p1_id)).'" style="color:inherit; text-decoration:none;">'.esc_html($p1_name).'</a>' : esc_html($p1_name);
                $p2_html = $p2_id ? '<a href="'.esc_url(get_permalink($p2_id)).'" style="color:inherit; text-decoration:none;">'.esc_html($p2_name).'</a>' : esc_html($p2_name);

                $is_home_scoring = ($team === 'Home' && !$is_og) || ($team === 'Away' && $is_og);

                if ($is_home_scoring) {
                    $scorer_line = '<div class="fs-scorer-row" style="margin-bottom: 8px; line-height: 1.2; text-align: left;">';
                    $scorer_line .= '<div>⚽ ' . $p1_html . ' ' . $lbl . '</div>';
                    if ($p2_name && !$is_og) $scorer_line .= '<div class="fs-scorer-assist" style="font-size: 11px; color: #999; margin-left: 18px; margin-top: 2px;">👟 ' . $p2_html . '</div>';
                    $scorer_line .= '</div>';
                    $home_scorers_html .= $scorer_line;
                } else {
                    $scorer_line = '<div class="fs-scorer-row" style="margin-bottom: 8px; line-height: 1.2; text-align: right;">';
                    $scorer_line .= '<div>' . $lbl . ' ' . $p1_html . ' ⚽</div>';
                    if ($p2_name && !$is_og) $scorer_line .= '<div class="fs-scorer-assist" style="font-size: 11px; color: #999; margin-right: 18px; margin-top: 2px;">' . $p2_html . ' 👟</div>';
                    $scorer_line .= '</div>';
                    $away_scorers_html .= $scorer_line;
                }
            } elseif ($type === 'card' && strpos($detail, 'yellow') !== false) { 
                if ($p1_id) $events_map[$p1_id]['yellows'][] = $min;
            } elseif ($type === 'card' && strpos($detail, 'red') !== false) { 
                if ($p1_id) $events_map[$p1_id]['reds'][] = $min;
            } elseif ($type === 'substitute') { 
                if ($p1_id) $events_map[$p1_id]['subs'][] = $min; 
                if ($p2_id) $events_map[$p2_id]['subs'][] = $min; 
            }
        }
    }

    // 4. LINEUPS
    $h_xi = []; $a_xi = []; $h_sub = []; $a_sub = [];
    if (!$is_fixture && !empty($data['player_stats'])) {
        foreach ($data['player_stats'] as $ps) {
            $pid = $ps['player_id'];
            $p_name = $ps['player_name'];
            $team_side = $ps['team'] ?? 'Home';
            $is_starter = $ps['is_starter'] ?? false;

            $cat = $ps['position'] ?? '';
            if ($cat === 'UNC') { $cat = ''; }
            $cat_html = $cat ? ' <span style="color:#aaa; font-size:10px;">' . esc_html($cat) . '</span>' : '';

            $ev_html = '';
            if (!empty($events_map[$pid]['goals'])) { foreach($events_map[$pid]['goals'] as $m) { $ev_html.='<span style="margin-left:5px;">⚽<small>'.$m.'</small></span>'; } }
            if (!empty($events_map[$pid]['yellows'])) { foreach($events_map[$pid]['yellows'] as $m) { $ev_html.='<span style="margin-left:5px;">🟨<small>'.$m.'</small></span>'; } }
            if (!empty($events_map[$pid]['reds'])) { foreach($events_map[$pid]['reds'] as $m) { $ev_html.='<span style="margin-left:5px;">🟥<small>'.$m.'</small></span>'; } }

            if (!empty($events_map[$pid]['subs'])) { 
                $unique_subs = array_unique($events_map[$pid]['subs']); 
                foreach($unique_subs as $m) { 
                    if ($is_starter) {
                        $ev_html.='<span style="margin-left:6px; font-size:12px; color:#d9534f; font-weight:900;">↓<small style="font-size:10px; font-weight:normal; color:#888;">'.$m.'</small></span>'; 
                    } else {
                        $ev_html.='<span style="margin-left:6px; font-size:12px; color:#5cb85c; font-weight:900;">↑<small style="font-size:10px; font-weight:normal; color:#888;">'.$m.'</small></span>'; 
                    }
                } 
            }

            $player_link = '<a href="'.esc_url(get_permalink($pid)).'" style="color:inherit; text-decoration:none; transition:color 0.2s;" onmouseover="this.style.color=\'#666\'" onmouseout="this.style.color=\'inherit\'">'.esc_html($p_name).'</a>';
            $line_html = '<li style="display:flex; justify-content:space-between; margin-bottom:8px; padding-bottom:4px; border-bottom:1px dashed rgba(0,0,0,0.05);"><span><strong>'.$player_link.'</strong>'.$cat_html.'</span><span>'.$ev_html.'</span></li>';

            if ($team_side === 'Home') {
                if ($is_starter) $h_xi[] = $line_html; else $h_sub[] = $line_html;
            } else {
                if ($is_starter) $a_xi[] = $line_html; else $a_sub[] = $line_html;
            }
        }
    }

    // 5. HTML STRUCTURE & CSS
    $wrap_class = 'fs-mg-' . uniqid();
    $out = '<style>
        .'.$wrap_class.' { background-color: #f9fbf9; padding: 40px; border: 1px solid #e0ebe0; border-radius: 8px; font-family: "Lato", sans-serif; color: #333; }
        .'.$wrap_class.' .fs-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 40px; border-bottom: 2px solid #e0ebe0; padding-bottom: 30px; }
        .'.$wrap_class.' .fs-team { flex: 1 1 0; min-width: 0; display: flex; align-items: flex-start; gap: 20px; }
        .'.$wrap_class.' .fs-team-info { flex: 1; min-width: 0; }
        .'.$wrap_class.' .fs-team.away { flex-direction: row-reverse; }
        .'.$wrap_class.' .fs-team.away .fs-team-info { text-align: right; }
        .'.$wrap_class.' .fs-logo-wrap { width: 80px; height: 80px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; background: #fff; border-radius: 50%; box-shadow: 0 4px 10px rgba(0,0,0,0.05); padding: 10px; }
        .'.$wrap_class.' .fs-logo { max-width: 100%; max-height: 100%; object-fit: contain; }
        .'.$wrap_class.' .fs-team-name { font-family: "Playfair Display", serif; font-size: clamp(16px, 2.2vw, 22px); font-weight: 900; text-transform: uppercase; line-height: 1.2; word-wrap: break-word; white-space: normal !important; overflow: visible !important; }
        .'.$wrap_class.' .fs-score { flex: 0 0 auto; text-align: center; font-size: 54px; font-family: "Playfair Display", serif; font-weight: 900; color: #111; margin: 0 20px; line-height: 1; }
        .'.$wrap_class.' .fs-kickoff { flex: 0 0 auto; text-align: center; background: #111; color: #fff; padding: 15px 25px; border-radius: 6px; margin: 0 20px; }
        .'.$wrap_class.' .fs-kickoff span { display: block; font-size: 10px; text-transform: uppercase; letter-spacing: 2px; color: #aaa; margin-bottom: 5px; }
        .'.$wrap_class.' .fs-kickoff strong { font-size: 28px; font-family: "Playfair Display", serif; font-weight: 900; }
        .'.$wrap_class.' .fs-lineups { display: flex; justify-content: space-between; margin-bottom: 30px; gap: 40px; }
        .'.$wrap_class.' .fs-lineup-col { flex: 1; background: #fff; padding: 25px; border-radius: 6px; box-shadow: 0 2px 8px rgba(0,0,0,0.02); }
        .'.$wrap_class.' .fs-lineup-col ul { list-style: none; padding: 0; margin: 0; font-size: 13px; color: #444; }
        .'.$wrap_class.' .fs-footer { background:#fff; border:1px solid #e0ebe0; border-radius: 6px; padding:20px; display:flex; justify-content:space-between; font-size:12px; font-weight:bold; color:#555; text-transform:uppercase; }
        .'.$wrap_class.' .fs-video-wrap { margin: 30px 0; border-radius: 8px; overflow: hidden; }
        .'.$wrap_class.' .fs-video-wrap iframe { width: 100%; aspect-ratio: 16/9; height: auto; }

        @media (max-width: 768px) {
            .'.$wrap_class.' { padding: 15px; } 
            .'.$wrap_class.' .fs-header { flex-wrap: wrap; justify-content: center; align-items: flex-start; padding-bottom: 20px; margin-bottom: 20px; gap: 15px; }
            .'.$wrap_class.' .fs-team, .'.$wrap_class.' .fs-team.away { flex-direction: column; align-items: center; width: 40%; gap: 10px; }
            .'.$wrap_class.' .fs-team-info, .'.$wrap_class.' .fs-team.away .fs-team-info { text-align: center !important; width: 100%; }
            .'.$wrap_class.' .fs-logo-wrap { width: 50px; height: 50px; padding: 5px; } 
            .'.$wrap_class.' .fs-score { width: 100%; font-size: 42px; margin: 10px 0; order: -1; } 
            .'.$wrap_class.' .fs-kickoff { width: 100%; margin: 10px 0; order: -1; }
            .'.$wrap_class.' .fs-team-name { font-size: 14px; line-height: 1.3; margin-bottom: 5px; }
            .'.$wrap_class.' .fs-scorer-row { text-align: center !important; }
            .'.$wrap_class.' .fs-scorer-assist { margin-left: 0 !important; margin-right: 0 !important; }
            .'.$wrap_class.' .fs-stats { flex-direction: column; gap: 30px; padding: 20px 15px !important; }
            .'.$wrap_class.' .fs-stats > div { width: 100% !important; }
            .'.$wrap_class.' .fs-lineups { flex-direction: column; gap: 20px; }
            .'.$wrap_class.' .fs-lineup-col { text-align: left !important; padding: 15px; }
            .'.$wrap_class.' .fs-footer { flex-direction: column; gap: 10px; align-items: center; text-align: center; }
        }
    </style>';

    $raw_content = get_post_field('post_content', $match_id);
    $raw_content = preg_replace('/\[fs_match_report_graphic.*?\]/', '', $raw_content);
    if (trim($raw_content)) {
        $out .= '<div class="fs-match-report-text" style="margin-bottom: 40px; font-family: \'Lato\', sans-serif; font-size: 16px; line-height: 1.8; color: #333;">' . do_shortcode(wpautop($raw_content)) . '</div>';
    }

    // START GRAPHIC WRAPPER
    $out .= '<div class="'.$wrap_class.'">';
    $out .= '<div style="text-align:center; text-transform:uppercase; font-size:11px; font-weight:bold; letter-spacing:2px; color:#888; margin-bottom:30px;">Match Week ' . get_field('match_week', $match_id) . ' • ' . $display_date . '</div>';

    // HEADER
    $out .= '<div class="fs-header">';
        $out .= '<div class="fs-team"><a href="'.esc_url($h_link).'"><div class="fs-logo-wrap"><img class="fs-logo" src="'.$h_logo.'"></div></a>';
        $out .= '<div class="fs-team-info"><div class="fs-team-name" style="color:'.$h_color.';"><a href="'.esc_url($h_link).'" style="color:inherit; text-decoration:none;">'.get_the_title($h_id).'</a></div>';
        if (!$is_fixture && $h_xg_disp !== null) $out .= '<div style="font-size:11px; color:#888; font-weight:bold; margin-top:4px;">XG '.$h_xg_disp.'</div>';
        $out .= '<div style="font-size:13px; margin-top:10px;">'.$home_scorers_html.'</div></div></div>';

        if ($is_fixture) {
            $out .= '<div class="fs-kickoff"><span>Kick Off</span><strong>'.$kick_off.'</strong></div>';
        } else {
            $out .= '<div class="fs-score">'.$h_score.'<span style="color:#ccc; margin:0 10px;">-</span>'.$a_score.'</div>';
        }

        $out .= '<div class="fs-team away"><a href="'.esc_url($a_link).'"><div class="fs-logo-wrap"><img class="fs-logo" src="'.$a_logo.'"></div></a>';
        $out .= '<div class="fs-team-info"><div class="fs-team-name" style="color:'.$a_color.';"><a href="'.esc_url($a_link).'" style="color:inherit; text-decoration:none;">'.get_the_title($a_id).'</a></div>';
        if (!$is_fixture && $a_xg_disp !== null) $out .= '<div style="font-size:11px; color:#888; font-weight:bold; margin-top:4px;">XG '.$a_xg_disp.'</div>';
        $out .= '<div style="font-size:13px; margin-top:10px;">'.$away_scorers_html.'</div></div></div>';
    $out .= '</div>';

    // PRE-MATCH PREVIEW OR POST-MATCH STATS
    if ($is_fixture) {
        $out .= '<div style="padding: 40px; text-align: center; background: #fff; border-radius: 6px; box-shadow: 0 2px 8px rgba(0,0,0,0.02); margin-bottom: 30px;">';
        $out .= '<h3 style="font-family:\'Playfair Display\', serif; font-size: 24px; font-weight: 900; margin: 0 0 10px 0; color: #111;">Match Preview</h3>';
        $out .= '<p style="color: #666; font-size: 14px; margin: 0;">Lineups, live events, and advanced statistical analysis will populate here automatically once the match kicks off.</p>';
        $out .= '</div>';
    } else {
        // EXTENDED ADVANCED STATS
        $h_poss = intval($get_stat('home_possession'));
        if ($h_poss === 0) $h_poss = 50; 

        $advanced_bars = [
            'Expected Goals (xG)' => ['home_xg', 'away_xg', true],
            'Total Attempts' => ['home_attempts', 'away_attempts', false],
            'Shots on Target' => ['home_on_target', 'away_on_target', false],
            'Shots off Target' => ['home_off_target', 'away_off_target', false],
            'Dangerous Attacks' => ['home_dangerous_attacks', 'away_dangerous_attacks', false],
            'Corners' => ['home_corners', 'away_corners', false],
            'Fouls' => ['home_fouls', 'away_fouls', false],
            'Offsides' => ['home_offsides', 'away_offsides', false]
        ];

        $out .= '<div class="fs-stats" style="display:flex; justify-content:space-between; align-items:center; margin-bottom:40px; background:#fff; padding:30px; border-radius:6px; box-shadow:0 2px 8px rgba(0,0,0,0.02);">';
            $out .= '<div style="width:30%; text-align:center;"><div style="font-size:12px; text-transform:uppercase; color:#777; font-weight:bold; margin-bottom:20px;">Possession</div>';
            $dash_h = max(0, $h_poss - 1.5);
            $out .= '<div style="position:relative; width:120px; height:120px; margin:0 auto;"><svg viewBox="0 0 42 42" style="transform: rotate(-90deg); overflow:visible;"><circle cx="21" cy="21" r="15.915" fill="none" stroke="'.$a_color.'" stroke-width="6"></circle><circle cx="21" cy="21" r="15.915" fill="none" stroke="'.$h_color.'" stroke-width="6" stroke-dasharray="'.$dash_h.' 100"></circle><circle cx="21" cy="21" r="15.915" fill="none" stroke="#f9fbf9" stroke-width="7" stroke-dasharray="1.5 98.5"></circle><circle cx="21" cy="21" r="15.915" fill="none" stroke="#f9fbf9" stroke-width="7" stroke-dasharray="1.5 98.5" stroke-dashoffset="-'.$dash_h.'"></circle></svg></div>';
            $out .= '<div style="display:flex; justify-content:space-between; margin-top:15px; padding:0 10%; font-weight:900; font-size:16px;"><span style="color:'.$h_color.'">'.$h_poss.'%</span><span style="color:'.$a_color.'">'.(100-$h_poss).'%</span></div></div>';

            $out .= '<div style="width:60%;">';
            foreach($advanced_bars as $label => $f) {
                $is_float = $f[2];
                $hv = $get_stat($f[0], $is_float); 
                $av = $get_stat($f[1], $is_float); 

                // Auto-Prune: Skip this bar entirely if FootyStats didn't track it
                if ($hv === 0 && $av === 0) continue;
                if ($hv === null && $av === null) continue;

                $hv_disp = $is_float ? number_format($hv, 2) : $hv;
                $av_disp = $is_float ? number_format($av, 2) : $av;

                $total = ($hv + $av) ?: 1; 
                $hp = ($hv / $total) * 100;

                $out .= '<div style="margin-bottom:22px;"><div style="display:flex; justify-content:space-between; font-size:12px; font-weight:900; text-transform:uppercase; margin-bottom:8px;"><span style="color:'.$h_color.'">'.$hv_disp.'</span><span style="color:#888;">'.$label.'</span><span style="color:'.$a_color.'">'.$av_disp.'</span></div><div style="display:flex; height:12px; background:#eee; border-radius:6px; overflow:hidden;"><div style="width:'.$hp.'%; background:'.$h_color.'; border-right:2px solid #fff;"></div><div style="flex-grow:1; background:'.$a_color.';"></div></div></div>';
            }
            $out .= '</div>';
        $out .= '</div>';

        // LINEUPS
        if (!empty($h_xi) || !empty($a_xi)) {
            $out .= '<div class="fs-lineups">';
                $out .= '<div class="fs-lineup-col"><h4 style="border-bottom:3px solid '.$h_color.'; padding-bottom:10px; margin-top:0; margin-bottom:20px; font-family:\'Playfair Display\', serif; font-size:18px;">Starting XI '.($h_formation?'<span style="color:#888; font-size:12px; font-family:\'Lato\', sans-serif;">('.$h_formation.')</span>':'').'</h4><ul>'.implode('',$h_xi).'</ul>';
                if(!empty($h_sub))$out .= '<h4 style="margin-top:30px; border-bottom:1px solid #eee; padding-bottom:10px; font-size:14px; color:#888; text-transform:uppercase;">Substitutes</h4><ul>'.implode('',$h_sub).'</ul>';
                $out .= '</div>';

                $out .= '<div class="fs-lineup-col" style="text-align:right;"><h4 style="border-bottom:3px solid '.$a_color.'; padding-bottom:10px; margin-top:0; margin-bottom:20px; font-family:\'Playfair Display\', serif; font-size:18px;">Starting XI '.($a_formation?'<span style="color:#888; font-size:12px; font-family:\'Lato\', sans-serif;">('.$a_formation.')</span>':'').'</h4><ul>'.implode('',$a_xi).'</ul>';
                if(!empty($a_sub))$out .= '<h4 style="margin-top:30px; border-bottom:1px solid #eee; padding-bottom:10px; font-size:14px; color:#888; text-transform:uppercase;">Substitutes</h4><ul>'.implode('',$a_sub).'</ul>';
                $out .= '</div>';
            $out .= '</div>';
        } else {
            $out .= '<div style="padding: 30px; text-align: center; color: #888; background: #fff; border-radius: 6px; margin-bottom: 30px;">Lineups not available for this match.</div>';
        }
    }

    // VIDEO HIGHLIGHTS
    $video_field = get_field('match_highlights', $match_id);
    if ($video_field) {
        if (strpos($video_field, '<iframe') !== false) {
            $out .= '<div class="fs-video-wrap">' . $video_field . '</div>';
        } else {
            $embed = wp_oembed_get($video_field);
            if ($embed) {
                $out .= '<div class="fs-video-wrap">' . $embed . '</div>';
            } else {
                $out .= '<div style="margin: 30px 0; text-align: center;"><a href="'.esc_url($video_field).'" target="_blank" style="display:inline-block; background:#0A3B25; color:#fff; padding:12px 25px; border-radius:4px; text-decoration:none; font-weight:900; text-transform:uppercase;">📺 Watch Match Highlights</a></div>';
            }
        }
    }

    // MOTM
    if(!$is_fixture && $motm) {
        $motm_id = $get_safe_id($motm);
        $out .= '<div style="text-align:center; border-top:1px solid #e0ebe0; padding-top:30px; margin-bottom:30px;"><small style="letter-spacing:2px; color:#777; font-weight:bold; text-transform:uppercase;">Man of the Match</small><div style="font-family:\'Playfair Display\',serif; font-size:26px; font-weight:800; margin-top:8px;"><a href="'.esc_url(get_permalink($motm_id)).'" style="color:#111; text-decoration:none; transition:opacity 0.2s;" onmouseover="this.style.opacity=0.7" onmouseout="this.style.opacity=1">'.get_the_title($motm_id).'</a></div></div>';
    }

    // FOOTER
    $stadium = get_field('stadium', $match_id) ?: 'Unknown';
    $referee = get_field('match_referee', $match_id) ?: '-';
    $att = number_format(intval(preg_replace('/[^0-9]/','',get_field('match_attendance',$match_id))));
    $out .= '<div class="fs-footer"><div>🏟️ STADIUM: '.$stadium.'</div><div>⚖️ REFEREE: '.$referee.'</div><div>🎟️ ATT: '.($att?:'-').'</div></div>';

    return $out . '</div>';
});

/**
 * Football Siam - Club Data Filler Hub (Spreadsheet Mode)
 * View and edit all club data on one screen.
 */

add_action('admin_menu', 'fs_register_club_filler_page');
function fs_register_club_filler_page() {
    add_submenu_page(
        'edit.php?post_type=club', 
        'Data Filler Hub', 
        'Data Filler Hub', 
        'manage_options', 
        'fs-club-filler', 
        'fs_club_filler_page_callback'
    );
}

function fs_club_filler_page_callback() {
    $fields_to_check = [
        'primary_colour'     => 'Colour',
        'club_nickname'      => 'Nickname',
        'head_coach'         => 'Coach',
        'owner'              => 'Owner',
        'last_season_finish' => 'Finish',
        'founded_year'       => 'Founded',
        'stadium_name'       => 'Stadium',
        'capacity'           => 'Capacity'
    ];

    // Handle Inline Save
    if (isset($_POST['fs_save_inline_club']) && check_admin_referer('fs_club_inline_nonce')) {
        $post_id = intval($_POST['club_id']);

        // Update the Club Name (Post Title) if it was changed
        if (isset($_POST['club_name'])) {
            wp_update_post([
                'ID'         => $post_id,
                'post_title' => sanitize_text_field($_POST['club_name'])
            ]);
        }

        // Update all ACF fields
        foreach ($fields_to_check as $key => $label) {
            if (isset($_POST['acf_fields'][$key])) {
                update_field($key, sanitize_text_field($_POST['acf_fields'][$key]), $post_id);
            }
        }
        echo '<div class="notice notice-success is-dismissible"><p>Data for <strong>' . esc_html($_POST['club_name']) . '</strong> updated.</p></div>';
    }

    echo '<div class="wrap" style="max-width: 98%;">';
    echo '<h1>🛡️ Club Data Filler Hub</h1>';
    echo '<p>Edit club details directly below. Fields with red borders are currently empty.</p>';

    $clubs = get_posts([
        'post_type'   => 'club',
        'numberposts' => -1,
        'orderby'     => 'title',
        'order'       => 'ASC'
    ]);

    echo '<table class="wp-list-table widefat fixed striped" style="margin-top:20px;">';
    echo '<thead><tr>
            <th width="150px">Club Name</th>';
            foreach ($fields_to_check as $label) {
                echo '<th>' . esc_html($label) . '</th>';
            }
    echo '<th width="80px">Action</th></tr></thead>';
    echo '<tbody>';

    foreach ($clubs as $club) {
        echo '<tr>';
        echo '<form method="POST">';
        wp_nonce_field('fs_club_inline_nonce');
        echo '<input type="hidden" name="club_id" value="' . $club->ID . '">';

        // 1. Club Name (Post Title)
        echo '<td><input type="text" name="club_name" value="' . esc_attr($club->post_title) . '" style="width:100%; font-weight:bold; border:none; background:transparent;"></td>';

        // 2. ACF Fields Loop
        foreach ($fields_to_check as $key => $label) {
            $val = get_field($key, $club->ID);
            $empty_style = empty($val) ? 'border: 1px solid #d63638; background: #fffcfc;' : 'border: 1px solid #ddd;';

            echo '<td>';
            echo '<input type="text" name="acf_fields[' . esc_attr($key) . ']" value="' . esc_attr($val) . '" style="width:100%; font-size:12px; ' . $empty_style . '" placeholder="...">';
            echo '</td>';
        }

        // 3. Save Button
        echo '<td><input type="submit" name="fs_save_inline_club" class="button button-small button-primary" value="Save"></td>';

        echo '</form>';
        echo '</tr>';
    }

    echo '</tbody></table>';
    echo '</div>';
}

/**
 * FOOTBALL SIAM - PLAYER IDENTITY HUB (v4.1 SUPER SIMPLE EDITION)
 * Fixed: Restored wide taxonomy query so it correctly finds players already assigned to T1/T2 clubs.
