// A. Fix Missing Data
add_action('wp_ajax_fs_save_player_root', function() {
    $pid = intval($_POST['pid']);
    if ($pid > 0) {
        wp_update_post(['ID' => $pid, 'post_title' => sanitize_text_field($_POST['title'])]);
        update_post_meta($pid, 'first_name', sanitize_text_field($_POST['first']));
        update_post_meta($pid, 'last_name', sanitize_text_field($_POST['last']));
        if (intval($_POST['club']) > 0) update_post_meta($pid, 'current_club', intval($_POST['club']));
        else delete_post_meta($pid, 'current_club'); 
        update_post_meta($pid, '_fs_identity_checked', 'yes');
        wp_send_json_success();
    }
    wp_send_json_error();
});

// B. 1-Click Bulk Merge
add_action('wp_ajax_fs_bulk_merge_players', function() {
    $master_id = intval($_POST['master_id']);
    $clone_ids = isset($_POST['clone_ids']) ? array_map('intval', (array)$_POST['clone_ids']) : [];

    if (!$master_id || empty($clone_ids)) wp_send_json_error('Invalid IDs');

    // Find every match in the database
    $matches = get_posts(['post_type' => 'matches', 'posts_per_page' => -1, 'fields' => 'ids']);

    foreach ($matches as $mid) {
        $updated = false;

        // 1. Update the Raw JSON Blob
        $raw_encoded = get_post_meta($mid, 'raw_match_data', true);
        if ($raw_encoded) {
            $json = base64_decode($raw_encoded);
            if ($json) {
                foreach ($clone_ids as $cid) {
                    if (strpos($json, (string)$cid) !== false) {
                        $json = str_replace('"player_id": '.$cid, '"player_id": '.$master_id, $json);
                        $json = str_replace('"p1_id": '.$cid, '"p1_id": '.$master_id, $json);
                        $json = str_replace('"p2_id": '.$cid, '"p2_id": '.$master_id, $json);
                        $updated = true;
                    }
                }
                if ($updated) update_post_meta($mid, 'raw_match_data', base64_encode($json));
            }
        }

        // 2. Update ACF Lineups
        $stats = get_field('player_stats', $mid);
        if ($stats) {
            $acf_updated = false;
            foreach ($stats as $k => $row) {
                $pid = is_array($row['player']) ? $row['player'][0] : $row['player'];
                if (in_array(intval($pid), $clone_ids)) { $stats[$k]['player'] = [$master_id]; $acf_updated = true; }
            }
            if ($acf_updated) { update_field('player_stats', $stats, $mid); $updated = true; }
        }

        // 3. Update ACF Match Events
        $events = get_field('match_events', $mid);
        if ($events) {
            $acf_updated = false;
            foreach ($events as $k => $ev) {
                $p1 = is_array($ev['primary_player'] ?? '') ? $ev['primary_player'][0] : ($ev['primary_player'] ?? '');
                $p2 = is_array($ev['secondary_player'] ?? '') ? $ev['secondary_player'][0] : ($ev['secondary_player'] ?? '');
                if (in_array(intval($p1), $clone_ids)) { $events[$k]['primary_player'] = [$master_id]; $acf_updated = true; }
                if (in_array(intval($p2), $clone_ids)) { $events[$k]['secondary_player'] = [$master_id]; $acf_updated = true; }
            }
            if ($acf_updated) { update_field('match_events', $events, $mid); $updated = true; }
        }
    }

    // Nuke the clones
    foreach ($clone_ids as $cid) { wp_delete_post($cid, true); }
    wp_send_json_success();
});

