function fs_render_player_hub_simple() {
    // A. Identify Target Clubs (RESTORED BROAD TAXONOMY QUERY)
    $t1_t2_clubs = get_posts([
        'post_type' => 'club', 
        'posts_per_page' => -1, 
        'fields' => 'ids', 
        'tax_query' => [
            'relation' => 'OR',
            ['taxonomy' => 'category', 'field' => 'slug', 'terms' => ['thai-league-1', 'thai-league-2', 't1', 't2']],
            ['taxonomy' => 'league', 'field' => 'slug', 'terms' => ['thai-league-1', 'thai-league-2', 't1', 't2']],
            ['taxonomy' => 'competition', 'field' => 'slug', 'terms' => ['thai-league-1', 'thai-league-2', 't1', 't2']]
        ]
    ]);

    // B. Fetch All Players
    $all_players = get_posts(['post_type' => 'player', 'posts_per_page' => -1]);

    $name_map = [];
    $missing_data = [];

    foreach ($all_players as $p) {
        $pid = $p->ID;
        $title = $p->post_title;
        $first = get_post_meta($pid, 'first_name', true);
        $last = get_post_meta($pid, 'last_name', true);
        $club_meta = get_post_meta($pid, 'current_club', true);
        $club_id = is_array($club_meta) ? intval($club_meta[0]) : intval($club_meta);

        // Filter: Only process if they are in a found T1/T2 club OR are a Free Agent (0)
        if (in_array($club_id, $t1_t2_clubs) || empty($club_id)) {
            // Group by name for duplicates
            $clean_name = strtolower(trim($title));
            $name_map[$clean_name][] = [
                'id' => $pid, 'title' => $title, 'first' => $first, 'last' => $last, 'club_id' => $club_id
            ];
        }
    }

    // C. Separate into Duplicates vs Missing Data
    $duplicates = [];
    foreach ($name_map as $name => $profiles) {
        if (count($profiles) > 1) {
            $duplicates[$name] = $profiles;
