function fs_get_club_color_v18($club_id = null) {
    if (!$club_id) $club_id = get_the_ID();
    $color = get_field('primary_colour', $club_id);
    return $color ? $color : '#0A3B25';
}

function fs_get_contrast_color_v18($hexcolor) {
    $hexcolor = ltrim($hexcolor, '#');
    if (strlen($hexcolor) == 3) {
        $r = hexdec(substr($hexcolor, 0, 1) . substr($hexcolor, 0, 1));
        $g = hexdec(substr($hexcolor, 1, 1) . substr($hexcolor, 1, 1));
        $b = hexdec(substr($hexcolor, 2, 1) . substr($hexcolor, 2, 1));
    } else {
        $r = hexdec(substr($hexcolor, 0, 2));
        $g = hexdec(substr($hexcolor, 2, 2));
        $b = hexdec(substr($hexcolor, 4, 2));
    }
    $yiq = (($r * 299) + ($g * 587) + ($b * 114)) / 1000;
    return ($yiq >= 160) ? '#1a1a1a' : '#ffffff';
}

function fs_club_resolve_id_v18($val) {
    if (is_string($val) && is_serialized($val)) $val = unserialize($val);
    if (is_array($val)) return is_object($val[0]) ? $val[0]->ID : (is_object($val) ? $val->ID : $val[0]);
    return is_object($val) ? $val->ID : $val;
}

function fs_is_national_team_v18($cid) {
    $terms = wp_get_post_terms($cid, ['league', 'competition']);
    if (!is_wp_error($terms) && !empty($terms)) {
        foreach ($terms as $t) {
            if (in_array(strtolower(trim($t->slug)), ['national', 'international'])) return true; 
        }
    }
    return false;
}

function fs_clean_comp_name_v18($c_name, $club_title, $season_key) {
    $c_name = preg_replace('/Thai League T\s*1/i', 'Thai League 1', $c_name);
    $is_modern = (strpos($season_key, '2024') !== false || strpos($season_key, '2025') !== false || strpos($season_key, '2026') !== false);

    if ($is_modern) {
        if (stripos($c_name, 'AFC Cup') !== false) return 'AFC Champions League Two';
        if (stripos($c_name, 'AFC Champions League') !== false && stripos($c_name, 'Elite') === false && stripos($c_name, 'Two') === false) {
            $club_title_lower = strtolower($club_title);
            if (strpos($club_title_lower, 'buriram') !== false || strpos($club_title_lower, 'bangkok') !== false) {
                return 'AFC Champions League Elite';
            } else {
                return 'AFC Champions League Two';
            }
        }
    }
    return $c_name;
}

