function fs_club_key_players_func_v18() {
    $cid = get_the_ID();
    $color = fs_get_club_color_v18($cid);
    $text_color = fs_get_contrast_color_v18($color);

    $scorer_query = get_posts([
        'post_type' => 'player', 'posts_per_page' => 1, 'meta_key' => 'current_season_goals', 'orderby' => 'meta_value_num', 'order' => 'DESC',
        'meta_query' => [['relation' => 'OR', ['key' => 'current_club', 'value' => '"'.$cid.'"', 'compare' => 'LIKE'], ['key' => 'current_club', 'value' => $cid, 'compare' => '=']]]
    ]);

    $assist_query = get_posts([
        'post_type' => 'player', 'posts_per_page' => 1, 'meta_key' => 'current_season_assists', 'orderby' => 'meta_value_num', 'order' => 'DESC',
        'meta_query' => [['relation' => 'OR', ['key' => 'current_club', 'value' => '"'.$cid.'"', 'compare' => 'LIKE'], ['key' => 'current_club', 'value' => $cid, 'compare' => '=']]]
    ]);

    $out = '<div class="fs-dynamic-header" style="background-color:' . $color . '; color:' . $text_color . ';">Key Players</div>';
    $out .= '<div class="fs-club-box" style="padding:0; font-family:\'Lato\', sans-serif;">';

    $render_player = function($player_arr, $meta_key, $label) use ($color) {
        if (empty($player_arr)) return '';
        $p = $player_arr[0];
        $val = get_post_meta($p->ID, $meta_key, true) ?: 0;
        if ($val <= 0) return '';
        $img = get_field('player_photo_url', $p->ID) ?: get_the_post_thumbnail_url($p->ID, 'thumbnail');
        $html = '<div style="display:flex; align-items:center; padding:15px; border-bottom:1px solid #eee;">';
        if ($img) $html .= '<img src="'.esc_url($img).'" style="width:40px; height:40px; border-radius:50%; object-fit:cover; border:2px solid '.$color.'; margin-right:15px;">';
        else $html .= '<div style="width:40px; height:40px; border-radius:50%; background:#eee; border:2px solid '.$color.'; margin-right:15px;"></div>';
        $html .= '<div style="flex:1;"><div style="font-size:10px; color:#888; text-transform:uppercase; font-weight:bold; letter-spacing:1px;">'.$label.'</div><a href="'.get_permalink($p->ID).'" style="font-size:14px; font-weight:900; color:#111; text-decoration:none;">'.get_the_title($p->ID).'</a></div>';
        $html .= '<div style="font-size:22px; font-weight:900; color:'.$color.';">'.$val.'</div></div>';
        return $html;
    };

    $scorer_html = $render_player($scorer_query, 'current_season_goals', 'Top Scorer');
    $assist_html = $render_player($assist_query, 'current_season_assists', 'Top Assister');
    if (!$scorer_html && !$assist_html) $out .= '<div style="padding:15px; text-align:center; color:#888; font-size:13px;">No data available.</div>';
    else $out .= $scorer_html . $assist_html;
    $out .= '</div>';
    return $out;
}
