function fs_get_club_matches_v18($cid, $type = 'results') {
    $args = [
        'post_type' => 'matches', 'posts_per_page' => 40, 'post_status' => 'publish', 'fields' => 'ids',
        'meta_query' => ['relation' => 'AND', ['relation' => 'OR', ['key' => 'home_team', 'value' => '"' . $cid . '"', 'compare' => 'LIKE'], ['key' => 'away_team', 'value' => '"' . $cid . '"', 'compare' => 'LIKE'], ['key' => 'home_team', 'value' => $cid, 'compare' => '='], ['key' => 'away_team', 'value' => $cid, 'compare' => '=']]]
    ];
    if ($type === 'results') $args['meta_query'][] = ['key' => 'home_score', 'value' => '', 'compare' => '!='];
    else $args['meta_query'][] = ['relation' => 'OR', ['key' => 'home_score', 'compare' => 'NOT EXISTS'], ['key' => 'home_score', 'value' => '', 'compare' => '=']];

    $post_ids = get_posts($args);
    $valid = [];
    foreach ($post_ids as $pid) {
        $raw_date = get_post_meta($pid, 'date', true);
        $ts = $raw_date ? strtotime((string)$raw_date) : 0;
        if (!$ts) continue; 
        $hid = fs_club_resolve_id_v18(get_post_meta($pid, 'home_team', true));
        $aid = fs_club_resolve_id_v18(get_post_meta($pid, 'away_team', true));
        $comp_name = 'Match';
        $terms = wp_get_post_terms($pid, ['competition', 'category']);
        if (!is_wp_error($terms) && !empty($terms)) { foreach($terms as $t) { if (strtolower($t->name) !== 'matches') { $comp_name = $t->name; break; } } }
        $raw_time = get_post_meta($pid, 'kick_off_time', true);
        $clean_time = ($raw_time && $raw_time !== '00:00:00' && $raw_time !== '00:00') ? date('H:i', strtotime($raw_time)) : 'TBC';
        $valid[] = ['ID' => $pid, 'hs' => get_post_meta($pid, 'home_score', true), 'as' => get_post_meta($pid, 'away_score', true), 'ts' => $ts, 'time' => $clean_time, 'mw' => get_post_meta($pid, 'match_week', true) ?: 'Cup', 'hid' => $hid, 'aid' => $aid, 'comp' => $comp_name];
    }
    usort($valid, function($a, $b) use ($type) { if ($a['ts'] == $b['ts']) return 0; return ($type === 'fixtures') ? ($a['ts'] - $b['ts']) : ($b['ts'] - $a['ts']); });
    return $valid;
}

function fs_render_club_match_row_v18($m, $cid, $type, $color) {
    $safe_text_color = (fs_get_contrast_color_v18($color) === '#1a1a1a') ? '#111111' : $color;
    $h_weight = ($m['hid'] == $cid) ? '900' : 'normal'; $a_weight = ($m['aid'] == $cid) ? '900' : 'normal';
    $h_color = ($m['hid'] == $cid) ? $safe_text_color : '#333'; $a_color = ($m['aid'] == $cid) ? $safe_text_color : '#333';
    $score_time = ($type == 'results') ? $m['hs'].' - '.$m['as'] : $m['time'];
    $bg = ($type == 'results') ? '#f9f9f9' : '#fff';
    $score_style = ($type == 'results') ? 'background:#cccccc; color:#111; padding:4px 10px; border-radius:4px; font-weight:900;' : 'font-size:12px; color:#111; font-weight:900; background:#f0f0f0; padding:4px 10px; border-radius:4px;';
    $mw_disp = is_numeric($m['mw']) ? 'MW ' . $m['mw'] : $m['mw'];
    $out = '<div class="fs-c-match-row" style="background:'.$bg.';"><div class="fs-c-match-date"><span>'.date('d M', $m['ts']).'</span><br><strong>'.$mw_disp.'</strong></div><div class="fs-c-match-team home" style="font-weight:'.$h_weight.'; color:'.$h_color.';">' . get_the_title($m['hid']) . '</div><div class="fs-c-match-score"><a href="'.get_permalink($m['ID']).'" style="text-decoration:none;"><span style="'.$score_style.'">' . $score_time . '</span></a></div><div class="fs-c-match-team away" style="font-weight:'.$a_weight.'; color:'.$a_color.';">' . get_the_title($m['aid']) . '</div></div>';
    return $out;
}

