// ==========================================
// 8. BUNDLED SEASON ANALYSIS & HISTORICAL RECORD
// ==========================================
add_shortcode('fs_club_advanced_stats', function() {
    $cid = get_the_ID();
    $club_title = get_the_title($cid);
    $color = fs_get_club_color_v18($cid);
    $text_color = fs_get_contrast_color_v18($color);

    $json_raw = get_post_meta($cid, 'fs_team_stats_json', true);
    if (empty($json_raw)) $json_raw = get_field('fs_team_stats_json', $cid); 

    $raw_data = [];
    if (is_array($json_raw)) {
        $raw_data = $json_raw;
    } elseif (is_string($json_raw) && !empty($json_raw)) {
        $decoded = json_decode($json_raw, true);
        if ($decoded === null) $decoded = json_decode(stripslashes($json_raw), true);
        if (is_array($decoded)) $raw_data = $decoded;
    }

    if (empty($raw_data) || !isset($raw_data['all_seasons_metrics']) || !is_array($raw_data['all_seasons_metrics'])) return '';
    $seasons_data = $raw_data['all_seasons_metrics'];

    krsort($seasons_data);
    $default_season_key = array_key_first($seasons_data);
    if (!$default_season_key) return '';

    $chart_instances = [];

    // CUSTOM SORTER LOGIC
    $sort_comps = function($a, $b) {
        $get_rank = function($name) {
            $n = strtolower($name);
            if (strpos($n, 'thai league') !== false || strpos($n, 'semi-pro') !== false || strpos($n, 'amateur') !== false) return 1;
            if (strpos($n, 'fa cup') !== false) return 2;
            if (strpos($n, 'league cup') !== false) return 3;
            if (strpos($n, 'champions cup') !== false || strpos($n, 'super cup') !== false) return 4;
            if (strpos($n, 'afc') !== false || strpos($n, 'champions league') !== false || strpos($n, 'acl') !== false || strpos($n, 'shopee') !== false || strpos($n, 'asean') !== false) return 5;
            return 6; 
        };
        $rankA = $get_rank($a['comp_name'] ?? '');
        $rankB = $get_rank($b['comp_name'] ?? '');
        if ($rankA === $rankB) return strcmp($a['comp_name'] ?? '', $b['comp_name'] ?? '');
        return $rankA <=> $rankB;
    };

    // --- 1. ADVANCED ANALYTICS BLOCK ---
    $out = '<div style="border:1px solid #eee; border-radius:4px; margin-bottom:40px; overflow:hidden; font-family:\'Lato\',sans-serif;">';
    $out .= '<div style="background:'.$color.'; color:'.$text_color.'; padding:12px 15px; font-weight:900; text-transform:uppercase; font-family:\'Playfair Display\',serif; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">';
    $out .= '<span>Season Analysis & Advanced Analytics</span>';

    if (count($seasons_data) > 1) {
        $out .= '<select class="fs-season-select" onchange="fsSwitchTeamSeason(this.value, \''.$cid.'\')" style="border-color:rgba(255,255,255,0.3); background:rgba(0,0,0,0.2); color:#fff; padding:6px 12px; font-weight:bold; border-radius:4px; cursor:pointer;">';
        foreach (array_keys($seasons_data) as $s_key) {
            $selected = ($s_key === $default_season_key) ? 'selected' : '';
            $out .= '<option value="'.esc_attr(str_replace([' ', '/', '(', ')'], '_', $s_key)).'" '.$selected.'>Season '.esc_html($s_key).'</option>';
        }
        $out .= '</select>';
    }
    $out .= '</div>';

    foreach ($seasons_data as $season_key => $data) {
        if (!is_array($data)) continue;
        $clean_key = str_replace([' ', '/', '(', ')'], '_', $season_key);
        $display = ($season_key === $default_season_key) ? 'block' : 'none';

        $out .= '<div id="fs-team-season-block-'.$cid.'-'.$clean_key.'" class="fs-team-season-block-'.$cid.'" style="display:'.$display.'; background:#fff;">';

        $out .= '<div style="padding:20px 20px 0 20px;">';
        $out .= '<h4 style="margin:0 0 12px 0; font-size:11px; color:#888; text-transform:uppercase; font-weight:900;">Competition Breakdown</h4>';
        $out .= '<div style="overflow-x:auto;"><table class="fs-player-table" style="border:1px solid #eee; width:100%;">';
        $out .= '<thead style="background:#f9f9f9;"><tr><th style="text-align:left; padding-left:15px;">Competition</th><th>MP</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th><th>GD</th><th>Win %</th></tr></thead><tbody>';

        $t_mp = $t_w = $t_d = $t_l = $t_gf = $t_ga = 0;
        $comps_to_loop = (isset($data['competitions']) && is_array($data['competitions'])) ? $data['competitions'] : [['comp_name' => 'Overall Match Data', 'stats' => $data]];

        usort($comps_to_loop, $sort_comps);

        foreach ($comps_to_loop as $c) {
            if (!is_array($c)) continue;

            $c_name = fs_clean_comp_name_v18($c['comp_name'] ?? 'Competition', $club_title, $season_key);
            $c_stats = (isset($c['stats']) && is_array($c['stats'])) ? $c['stats'] : [];

            // Read MP from either new direct Python stamp or old FootyStats variables
            $mp = intval($c_stats['_mp'] ?? $c_stats['seasonMatchesPlayed_overall'] ?? $c_stats['matches_played_overall'] ?? $c_stats['matches_played'] ?? 0);

            // Safe fallback for old data
            $w = intval($c_stats['_w'] ?? $c_stats['seasonWins_overall'] ?? $c_stats['wins_overall'] ?? $c_stats['matches_won_overall'] ?? $c_stats['wins'] ?? 0);
            $d = intval($c_stats['_d'] ?? $c_stats['seasonDraws_overall'] ?? $c_stats['draws_overall'] ?? $c_stats['matches_drawn_overall'] ?? $c_stats['draws'] ?? 0);
            $l = intval($c_stats['_l'] ?? $c_stats['seasonLosses_overall'] ?? $c_stats['losses_overall'] ?? $c_stats['matches_lost_overall'] ?? $c_stats['losses'] ?? 0);

            if ($mp === 0 && ($w + $d + $l) > 0) $mp = $w + $d + $l;
            if ($mp === 0) continue; 

            $gf = intval($c_stats['_gf'] ?? $c_stats['seasonGoals_overall'] ?? $c_stats['goals_scored_overall'] ?? $c_stats['goalsFor'] ?? 0);
            $ga = intval($c_stats['_ga'] ?? $c_stats['seasonConceded_overall'] ?? $c_stats['goals_conceded_overall'] ?? $c_stats['goalsAgainst'] ?? 0);

            $gd = $gf - $ga;
            $gd_str = ($gd > 0 ? '+' : '') . $gd;
            $win_pct = $mp > 0 ? round(($w / $mp) * 100) . '%' : '0%';

            $t_mp += $mp; $t_w += $w; $t_d += $d; $t_l += $l; $t_gf += $gf; $t_ga += $ga;

            $out .= '<tr>';
            $out .= '<td style="text-align:left; padding-left:15px; font-weight:bold; color:'.$color.';">'.esc_html($c_name).'</td>';
            $out .= '<td>'.$mp.'</td><td style="color:#0e3622; font-weight:bold;">'.$w.'</td><td style="color:#888;">'.$d.'</td><td style="color:#d93025; font-weight:bold;">'.$l.'</td>';
            $out .= '<td>'.$gf.'</td><td>'.$ga.'</td><td style="font-weight:900;">'.$gd_str.'</td><td>'.$win_pct.'</td>';
            $out .= '</tr>';
        }

