/**
 * FOOTBALL SIAM - PLAYER PROFILE ENGINE (v6.17)
 * Featuring: Brutal Season Normalisation, Future Clamping, and Forced UI Overrides
 */

// ==========================================
// 1. DATA HELPERS & CLEANERS
// ==========================================
function fs_clean_club_name($name) {
    $replacements = [
        'Bangkok Glass' => 'Pathum United',
        'Port FC' => 'Port'
    ];
    return str_ireplace(array_keys($replacements), array_values($replacements), $name);
}

function fs_p_clean_comp_name($raw_name, $club_title = '') {
    $n = strtolower(trim($raw_name));

    if (strpos($n, 'friend') !== false || strpos($n, 'president') !== false || strpos($n, 'warm') !== false || strpos($n, 'charity') !== false) return 'Friendlies';
    if (strpos($n, 'fa cup') !== false) return 'FA Cup';
    if (strpos($n, 'league cup') !== false) return 'League Cup';
    if (strpos($n, 'thai league 3 cup') !== false || strpos($n, 'bgc') !== false) return 'Thai League 3 Cup';
    if (strpos($n, 'champions cup') !== false || strpos($n, 'super cup') !== false) return 'Champions Cup';

    if (strpos($n, 'afc') !== false || strpos($n, 'champions league') !== false || strpos($n, 'acl') !== false) {
        if (strpos($n, 'two') !== false || strpos($n, ' 2') !== false) return 'AFC Champions League Two';
        if (strpos($n, 'elite') !== false) return 'AFC Champions League Elite';
        $club_title_lower = strtolower($club_title);
        if (strpos($club_title_lower, 'buriram') !== false || strpos($club_title_lower, 'bangkok') !== false || strpos($club_title_lower, 'pathum') !== false) {
            return 'AFC Champions League Elite';
        }
        return 'AFC Champions League Two';
    }

    if (strpos($n, 'asean') !== false || strpos($n, 'shopee') !== false) return 'ASEAN Club Championship';
    if (strpos($n, 'thai league 1') !== false || strpos($n, 't1') !== false) return 'Thai League 1';
    if (strpos($n, 'thai league 2') !== false || strpos($n, 't2') !== false) return 'Thai League 2';
    if (strpos($n, 'thai league 3') !== false || strpos($n, 't3') !== false) return 'Thai League 3';
    if (trim($n) === 'thai league') return 'Thai League 1';

    return ucwords(trim($raw_name));
}

function fs_p_format_season($raw_season) {
    // Brutal Strip: Remove absolutely everything except numbers and forward slashes
    $s = preg_replace('/[^0-9\/]/', '', (string)$raw_season);

    if (preg_match('/^(\d{4})\/(\d{2})$/', $s, $matches)) {
        $year1 = $matches[1];
        $year2 = substr($year1, 0, 2) . $matches[2];
        $s = $year1 . '/' . $year2;
    }

    // Determine the current domestic start year (Thai season shifts in July/August)
    $current_start_year = (intval(date('n')) >= 7) ? intval(date('Y')) : intval(date('Y')) - 1;

    // Clamp ghost future seasons (like "2027/2028") to the current active season
    if (preg_match('/^(\d{4})\/(\d{4})$/', $s, $matches)) {
        $start_year = intval($matches[1]);
        if ($start_year > $current_start_year) {
            return $current_start_year . '/' . ($current_start_year + 1);
        }
        return $s;
    }

    // Clamp ghost future years (like "2027") to the current active season
    if (is_numeric($s) && strlen($s) == 4) {
        $year = intval($s);
        if ($year > $current_start_year) {
            return $current_start_year . '/' . ($current_start_year + 1);
        }
        if ($year >= 2016) {
            return $year . '/' . ($year + 1);
        }
    }

    return $s;
}

function fs_p_aggregate_season_metrics($all_seasons_metrics) {
    if (empty($all_seasons_metrics)) return [];
    $formatted = [];

    foreach ($all_seasons_metrics as $raw_key => $s_m) {
        $f_key = fs_p_format_season($raw_key);
        if (!isset($formatted[$f_key])) {
            $formatted[$f_key] = $s_m;
        } else {
            $keys_to_sum = [
                'appearances_overall', 'minutes_played_overall', 'goals_overall', 'assists_overall', 'conceded_overall', 'clean_sheets_overall',
                'appearances_home', 'minutes_played_home', 'goals_home', 'assists_home', 'conceded_home', 'clean_sheets_home',
                'appearances_away', 'minutes_played_away', 'goals_away', 'assists_away', 'conceded_away', 'clean_sheets_away',
                'yellow_cards_overall', 'red_cards_overall', 'penalty_misses', 'penalty_goals'
            ];
            foreach ($keys_to_sum as $k) {
                $formatted[$f_key][$k] = intval($formatted[$f_key][$k] ?? 0) + intval($s_m[$k] ?? 0);
            }
            $p_g = intval($formatted[$f_key]['penalty_goals'] ?? 0);
            $p_m = intval($formatted[$f_key]['penalty_misses'] ?? 0);
            if (($p_g + $p_m) > 0) {
                $formatted[$f_key]['penalty_success'] = round(($p_g / ($p_g + $p_m)) * 100);
            }

            // Retain detailed metrics if they exist
            if (empty($formatted[$f_key]['detailed']) && !empty($s_m['detailed'])) {
                $formatted[$f_key]['detailed'] = $s_m['detailed'];
            } elseif (($s_m['appearances_overall'] ?? 0) > ($formatted[$f_key]['appearances_overall'] ?? 0) && !empty($s_m['detailed'])) {
                $formatted[$f_key]['detailed'] = $s_m['detailed'];
            }
        }
    }

    uksort($formatted, function($a, $b) {
        $ya = intval(substr(trim($a), 0, 4));
        $yb = intval(substr(trim($b), 0, 4));
        if ($ya === $yb) return strcmp($b, $a);
        return $yb - $ya;
    });

    return $formatted;
}

function fs_resolve_player_club_id($val) {
    if (is_string($val) && is_serialized($val)) $val = unserialize($val);
    if (is_array($val)) return is_object($val[0]) ? $val[0]->ID : (is_object($val) ? $val->ID : $val[0]);
    return is_object($val) ? $val->ID : $val;
}

function fs_p_club($pid) {
    $c = get_field('current_club', $pid);
    return $c ? fs_resolve_player_club_id($c) : false;
}

function fs_p_color($pid) {
    $cid = fs_p_club($pid);
    return $cid ? (get_field('primary_colour', $cid) ?: '#1a1a1a') : '#1a1a1a';
}

function fs_p_contrast($hex) {
    $hex = ltrim($hex, '#');
    if (strlen($hex) == 3) {
        $r = hexdec(substr($hex,0,1).substr($hex,0,1));
        $g = hexdec(substr($hex,1,1).substr($hex,1,1));
        $b = hexdec(substr($hex,2,1).substr($hex,2,1));
    } else {
        $r = hexdec(substr($hex,0,2));
        $g = hexdec(substr($hex,2,2));
        $b = hexdec(substr($hex,4,2));
    }
    $yiq = (($r*299)+($g*587)+($b*114))/1000;
    return ($yiq >= 160) ? '#1a1a1a' : '#ffffff';
}

function fs_p_logo($cid) {
    if (!$cid) return '';
    $url = get_field('club_logo_url', $cid);
    return $url ?: (get_the_post_thumbnail_url($cid, 'thumbnail') ?: '');
}

function fs_p_age_dob($pid, $json) {
    $dob_raw = get_field('date_of_birth', $pid);
    $dob_str = '-';
    $age_str = '-';
    $ts = 0;

    if ($dob_raw && is_numeric($dob_raw)) {
        $ts = strtotime($dob_raw);
    } elseif ($dob_raw) {
        $ts = strtotime($dob_raw);
    } elseif (!empty($json['bio']['birthday'])) {
        $ts = intval($json['bio']['birthday']);
    }

    if ($ts > 0) {
        $dob_str = date('j M Y', $ts);
        $birthDate = new DateTime(date('Y-m-d', $ts));
        $today = new DateTime('today');
        $age_str = $birthDate->diff($today)->y . ' yrs';
    }

    return ['dob' => $dob_str, 'age' => $age_str];
}

