// ==========================================
// 5. CURRENT SEASON BREAKDOWN [fs_player_season_stats]
// ==========================================
function fs_get_player_match_log($pid) {
    static $cache = [];
    if (isset($cache[$pid])) return $cache[$pid];

    $club_id = fs_p_club($pid);
    if (!$club_id) return []; 

    $args = [
        'post_type' => 'matches', 'posts_per_page' => 150, 'post_status' => 'publish',
        'meta_key' => 'date', 'orderby' => 'meta_value', 'order' => 'DESC',
        'meta_query' => [
            'relation' => 'AND',
            ['key' => 'home_score', 'value' => '', 'compare' => '!='],
            [
                'relation' => 'OR',
                ['key' => 'home_team', 'value' => '"'.$club_id.'"', 'compare' => 'LIKE'],
                ['key' => 'away_team', 'value' => '"'.$club_id.'"', 'compare' => 'LIKE'],
                ['key' => 'home_team', 'value' => $club_id, 'compare' => '='],
                ['key' => 'away_team', 'value' => $club_id, 'compare' => '=']
            ]
        ]
    ];

    $matches = get_posts($args);
    $log = [];

    foreach ($matches as $m) {
        $mid = $m->ID;
        $played = false;
        $mins = 0; $g = 0; $a = 0; $y = 0; $r = 0;

        $raw_data = get_field('raw_match_data', $mid, false);
        $data = [];
        if (!empty($raw_data)) {
            $decoded = base64_decode(trim($raw_data));
            if ($decoded && is_array(json_decode($decoded, true))) { $data = json_decode($decoded, true); } 
            else { $fallback = json_decode(trim($raw_data), true); if (is_array($fallback)) $data = $fallback; }
        }

        if (!empty($data)) {
            if (!empty($data['player_stats'])) {
                foreach ($data['player_stats'] as $row) {
                    if ($row['player_id'] == $pid) { $played = true; $mins = (int)($row['minutes_played'] ?? 0); break; }
                }
            }
            if (!empty($data['match_events'])) {
                foreach ($data['match_events'] as $ev) {
                    $type = strtolower(trim($ev['event_type'] ?? ''));
                    $detail = strtolower(trim($ev['event_detail'] ?? ''));
                    $p1 = $ev['p1_id'] ?? 0;
                    $p2 = $ev['p2_id'] ?? 0;

                    if ($type === 'goal' && strpos($detail, 'missed') === false) {
                        if ($p1 == $pid) { $g++; $played = true; }
                        if ($p2 == $pid && strpos($detail, 'own') === false) { $a++; $played = true; }
                    }
                    if ($type === 'card' && strpos($detail, 'yellow') !== false) { if ($p1 == $pid) { $y++; $played = true; } }
                    if ($type === 'card' && strpos($detail, 'red') !== false) { if ($p1 == $pid) { $r++; $played = true; } }
                }
            }
        }
        if (!$played) continue; 

        $comp_name = 'Match';
        $terms = wp_get_post_terms($mid, ['competition', 'category']);
        if (!is_wp_error($terms) && !empty($terms)) {
            foreach($terms as $t) { if (strtolower($t->name) !== 'matches') { $comp_name = $t->name; break; } }
        }
        if ($comp_name === 'Match') $comp_name = get_post_meta($mid, 'competition', true) ?: 'Match';

        $comp_name = fs_p_clean_comp_name($comp_name, get_the_title($club_id));

        $log[] = ['mid' => $mid, 'comp' => $comp_name, 'mins' => $mins, 'g' => $g, 'a' => $a, 'y' => $y, 'r' => $r];
    }

    $cache[$pid] = $log;
    return $log;
}

add_shortcode('fs_player_season_stats', function() {
    $pid = get_the_ID(); $c = fs_p_color($pid); $tc = fs_p_contrast($c);
    $log = fs_get_player_match_log($pid);

    if (empty($log)) return '';

    $json_raw = get_field('fs_advanced_stats_json', $pid);
    $json = !empty($json_raw) ? json_decode($json_raw, true) : [];

    $season_raw = $json['latest_season_metrics']['season'] ?? date('Y') . '/' . (date('Y') + 1);
    $season_title = fs_p_format_season($season_raw);

    $stats = [];
    $tot = ['apps'=>0, 'mins'=>0, 'g'=>0, 'a'=>0, 'y'=>0, 'r'=>0];

    foreach ($log as $m) {
        $comp = $m['comp'];
        if (!isset($stats[$comp])) $stats[$comp] = ['apps'=>0, 'mins'=>0, 'g'=>0, 'a'=>0, 'y'=>0, 'r'=>0];
        $stats[$comp]['apps']++; $stats[$comp]['mins'] += $m['mins']; $stats[$comp]['g'] += $m['g']; 
        $stats[$comp]['a'] += $m['a']; $stats[$comp]['y'] += $m['y']; $stats[$comp]['r'] += $m['r'];
        $tot['apps']++; $tot['mins'] += $m['mins']; $tot['g'] += $m['g']; $tot['a'] += $m['a']; $tot['y'] += $m['y']; $tot['r'] += $m['r'];
    }

    $out = '<div style="border:1px solid #eee; border-radius:4px; margin-bottom:30px; overflow:hidden; font-family:\'Lato\',sans-serif;">';
    $out .= '<div style="background:'.$c.'; color:'.$tc.'; padding:12px 15px; font-weight:900; text-transform:uppercase; font-family:\'Playfair Display\',serif;">Current Season '.$season_title.' Breakdown</div>';
    $out .= '<div style="overflow-x:auto;"><table class="fs-player-table">';
    $out .= '<thead><tr><th style="text-align:left; padding-left:15px;">Competition</th><th>Apps</th><th>Mins</th><th>Goals</th><th>Assists</th><th>Yellow</th><th>Red</th></tr></thead><tbody>';

    foreach ($stats as $comp => $s) {
        $mins_disp = $s['mins'] > 0 ? $s['mins'] . '\'' : '-';
        $out .= '<tr><td style="text-align:left; padding-left:15px; font-weight:bold; color:'.$c.';">'.esc_html($comp).'</td>';
        $out .= '<td>'.$s['apps'].'</td><td>'.$mins_disp.'</td><td style="font-weight:bold;">'.$s['g'].'</td><td>'.$s['a'].'</td><td>'.$s['y'].'</td><td>'.$s['r'].'</td></tr>';
    }

    $tot_mins_disp = $tot['mins'] > 0 ? $tot['mins'] . '\'' : '-';
    $out .= '<tr style="background:'.$c.'; color:'.$tc.'; font-weight:900;">';
    $out .= '<td style="text-align:left; padding-left:15px; text-transform:uppercase;">Total</td>';
    $out .= '<td>'.$tot['apps'].'</td><td>'.$tot_mins_disp.'</td><td>'.$tot['g'].'</td><td>'.$tot['a'].'</td><td>'.$tot['y'].'</td><td>'.$tot['r'].'</td></tr>';
    $out .= '</tbody></table></div></div>';

    return $out;
});

