        $out .= '<tr><td style="text-align:left; padding-left:15px; font-weight:bold;">Home</td><td>'.intval($s_m['appearances_home']??0).'</td><td>'.intval($s_m['minutes_played_home']??0).'\'</td><td style="font-weight:bold; color:'.$c.';">'.intval($s_m['goals_home']??0).'</td><td>'.intval($s_m['assists_home']??0).'</td><td>'.intval($s_m['conceded_home']??0).'</td><td>'.intval($s_m['clean_sheets_home']??0).'</td></tr>';
        $out .= '<tr><td style="text-align:left; padding-left:15px; font-weight:bold;">Away</td><td>'.intval($s_m['appearances_away']??0).'</td><td>'.intval($s_m['minutes_played_away']??0).'\'</td><td style="font-weight:bold; color:'.$c.';">'.intval($s_m['goals_away']??0).'</td><td>'.intval($s_m['assists_away']??0).'</td><td>'.intval($s_m['conceded_away']??0).'</td><td>'.intval($s_m['clean_sheets_away']??0).'</td></tr>';

