function fs_render_career_table($career_subset, $c, $is_intl = false) {
    if (empty($career_subset)) return '';

    $out = '<div style="overflow-x:auto;"><table class="fs-player-table">';
    $out .= '<thead><tr style="background:#f9f9f9; text-align:left; font-size:11px; color:#888; text-transform:uppercase;">';
    $out .= '<th style="padding-left:15px; width:40px;"></th>';
    $out .= '<th style="text-align:left;">Season</th>';
    $out .= '<th style="text-align:left;">'.($is_intl ? 'National Team' : 'Club').'</th>';
    $out .= '<th>MP</th><th>Goals</th><th>Assists</th>';
    $out .= '<th><span style="display:inline-block; width:12px; height:16px; background:#f1c40f; border-radius:2px;"></span></th>'; 
    $out .= '<th><span style="display:inline-block; width:12px; height:16px; background:#e74c3c; border-radius:2px;"></span></th>'; 
    $out .= '<th>Pen</th><th>Min\'</th>';
