add_shortcode('fs_player_career_history', function() {
    $pid = get_the_ID(); $c = fs_p_color($pid); $tc = fs_p_contrast($c);

    $json_raw = get_field('fs_advanced_stats_json', $pid);
    $data = !empty($json_raw) ? json_decode($json_raw, true) : [];
    $raw_career = $data['career_history_rich'] ?? [];

    $out = '<div style="border:1px solid #eee; border-radius:4px; margin-bottom:40px; overflow:hidden; font-family:\'Lato\',sans-serif;">';
    $out .= '<div style="background:'.$c.'; color:'.$tc.'; padding:12px 15px; font-weight:900; text-transform:uppercase; font-family:\'Playfair Display\',serif;">Domestic Career History</div>';

    if (empty($raw_career)) { 
        return $out . '<div style="padding:20px; text-align:center; color:#888; background:#fff;">No history data available.</div></div>'; 
    }

    $agg_career = [];
    foreach($raw_career as $row) { 
        $raw_season = $row['season'] ?? '';
        $f_season = fs_p_format_season($raw_season);

        $club_raw = $row['club_name'] ?? '';
        $is_intl = preg_match('/(Thailand|National Team|U23|U-23|U21|U-21|U19|U-19)/i', $club_raw);
        $club_clean = fs_clean_club_name($club_raw);

        if ($is_intl) {
            $nation = get_field('national_team', $pid) ?: (get_field('nationality', $pid) ?: 'National Team');
            $club_clean = preg_match('/(U23|U-23)/i', $club_raw) ? $nation . ' U23' : $nation;
        }

        $key = $f_season . '_' . $club_clean . '_' . ($is_intl ? 'intl' : 'dom');

        if (!isset($agg_career[$key])) {
            $agg_career[$key] = [
                'season' => $f_season, 'club_name' => $club_clean, 'is_intl' => $is_intl,
                'apps' => 0, 'goals' => 0, 'assists' => 0, 'yellows' => 0, 'reds' => 0, 'pens' => 0, 'mins' => 0,
                'competitions' => []
            ];
        }

        foreach($row['competitions'] as $comp) {
            $clean_c_name = fs_p_clean_comp_name($comp['name'], $club_raw);

            if (!isset($agg_career[$key]['competitions'][$clean_c_name])) {
                $agg_career[$key]['competitions'][$clean_c_name] = [
                    'name' => $clean_c_name, 'apps' => 0, 'goals' => 0, 'assists' => 0,
                    'yellows' => 0, 'reds' => 0, 'pens' => 0, 'mins' => 0
                ];
            }

            $agg_career[$key]['competitions'][$clean_c_name]['apps'] += intval($comp['apps'] ?? 0);
            $agg_career[$key]['competitions'][$clean_c_name]['goals'] += intval($comp['goals'] ?? 0);
            $agg_career[$key]['competitions'][$clean_c_name]['assists'] += intval($comp['assists'] ?? 0);
            $agg_career[$key]['competitions'][$clean_c_name]['yellows'] += intval($comp['yellows'] ?? 0);
            $agg_career[$key]['competitions'][$clean_c_name]['reds'] += intval($comp['reds'] ?? 0);
            $agg_career[$key]['competitions'][$clean_c_name]['pens'] += intval($comp['pens'] ?? 0);
            $agg_career[$key]['competitions'][$clean_c_name]['mins'] += intval($comp['mins'] ?? 0);

            $agg_career[$key]['apps'] += intval($comp['apps'] ?? 0);
            $agg_career[$key]['goals'] += intval($comp['goals'] ?? 0);
            $agg_career[$key]['assists'] += intval($comp['assists'] ?? 0);
            $agg_career[$key]['yellows'] += intval($comp['yellows'] ?? 0);
            $agg_career[$key]['reds'] += intval($comp['reds'] ?? 0);
            $agg_career[$key]['pens'] += intval($comp['pens'] ?? 0);
            $agg_career[$key]['mins'] += intval($comp['mins'] ?? 0);
        }
    }

    $dom_career = [];
    $intl_career = [];
    foreach ($agg_career as $row) {
        if ($row['apps'] > 0) {
            $row['competitions'] = array_values($row['competitions']);
            if ($row['is_intl']) $intl_career[] = $row;
            else $dom_career[] = $row;
        }
    }

    $sort_fn = function($a, $b) {
        $year_a = intval(substr(trim($a['season']), 0, 4));
        $year_b = intval(substr(trim($b['season']), 0, 4));
        if ($year_a === $year_b) return strcmp($b['season'], $a['season']);
        return $year_b - $year_a;
    };
    usort($dom_career, $sort_fn);
    usort($intl_career, $sort_fn);

    if (!empty($dom_career)) {
        $c_labels = []; $c_apps = []; $c_goals = []; $c_assists = [];
        foreach(array_reverse($dom_career) as $dc) {
            $c_labels[] = $dc['season'];
            $c_apps[] = $dc['apps'];
            $c_goals[] = $dc['goals'];
            $c_assists[] = $dc['assists'];
