        $canvas_id = "fs_career_chart_" . $pid;

        $out .= '<div style="padding:20px; background:#fff; border-bottom:1px solid #eee;">';
        $out .= '<h4 style="margin:0 0 15px 0; font-size:12px; color:#888; text-transform:uppercase; font-weight:900;">Career Progression</h4>';
        $out .= '<div style="position:relative; height:250px; width:100%;"><canvas id="'.$canvas_id.'"></canvas></div>';
        $out .= '</div>';

        $js = "document.addEventListener('DOMContentLoaded', function() { var ctx = document.getElementById('{$canvas_id}'); if (ctx) { new Chart(ctx, { type: 'bar', data: { labels: ".json_encode($c_labels).", datasets: [ { label: 'Appearances', data: ".json_encode($c_apps).", type: 'line', borderColor: '#111', borderWidth: 2, fill: false, tension: 0.3, pointBackgroundColor: '#111', order: 1 }, { label: 'Goals', data: ".json_encode($c_goals).", backgroundColor: '{$c}', borderRadius: 3, order: 2 }, { label: 'Assists', data: ".json_encode($c_assists).", backgroundColor: '#bdc3c7', borderRadius: 3, order: 2 } ] }, options: { responsive: true, maintainAspectRatio: false, plugins: { legend: { position: 'top', labels: { boxWidth: 12, font: { size: 10 } } } }, scales: { y: { beginAtZero: true, ticks: { precision: 0 } }, x: { grid: { display: false } } } } }); } });";
        $out .= '<script type="text/javascript">/* <![CDATA[ */ ' . $js . ' /* ]]> */</script>';
    }

    $out .= fs_render_career_table($dom_career, $c, false);
    $out .= '</div>';

    if (!empty($intl_career)) {
        $out .= '<div style="border:1px solid #eee; border-radius:4px; margin-bottom:40px; overflow:hidden; font-family:\'Lato\',sans-serif;">';
        $out .= '<div style="background:'.$c.'; color:'.$tc.'; padding:12px 15px; font-weight:900; text-transform:uppercase; font-family:\'Playfair Display\',serif;">International Career History</div>';
        $out .= fs_render_career_table($intl_career, $c, true);
        $out .= '</div>';
    }

    return $out;
});

