add_shortcode('fs_player_advanced_stats', function() {
    $pid = get_the_ID(); $c = fs_p_color($pid); $tc = fs_p_contrast($c);
    $json_string = get_field('fs_advanced_stats_json', $pid);
    if (empty($json_string)) return '';

    $raw_data = json_decode($json_string, true);

    $all_seasons_metrics = fs_p_aggregate_season_metrics($raw_data['all_seasons_metrics'] ?? []);

    $target_season = [];
    if (!empty($all_seasons_metrics)) {
        foreach($all_seasons_metrics as $season_key => $sm) {
            if (($sm['appearances_overall'] ?? 0) > 0) {
                $target_season = $sm;
                break; 
            }
        }
    }

    $data = $target_season ?: ($raw_data['latest_season_metrics'] ?? []);
    if (!is_array($data) || empty($data)) return '';

    $det = $data['detailed'] ?? [];

    $out = '<div style="margin-bottom:40px; font-family:\'Lato\',sans-serif;">';

    $format_val = function($val, $type = 'int') {
        if (empty($val) || $val == 0) return 'N/A';
        if ($type === 'float') return number_format((float)$val, 2);
        if ($type === 'percent') return intval($val) . '%';
        return intval($val);
    };

    $groups = [
        'Attacking Metrics' => [
            ['label' => 'Goals p/90', 'val' => number_format((float)($data['goals_per_90_overall'] ?? 0), 2)],
            ['label' => 'Expected Goals (xG)', 'val' => number_format((float)($det['xg_total_overall'] ?? $data['xg_total_overall'] ?? 0), 2)],
            ['label' => 'Non-Penalty xG', 'val' => number_format((float)($det['npxg_total_overall'] ?? 0), 2)],
            ['label' => 'Shot Conversion', 'val' => $format_val($det['shot_conversion_rate_overall'] ?? $data['shot_conversion_rate_overall'] ?? 0, 'percent')]
        ],
        'Playmaking & Passing' => [
            ['label' => 'Pass Completion', 'val' => $format_val($det['pass_completion_rate_overall'] ?? $data['pass_completion_rate_overall'] ?? 0, 'percent')],
            ['label' => 'Expected Assists (xA)', 'val' => number_format((float)($det['xa_total_overall'] ?? $data['xa_total_overall'] ?? 0), 2)],
            ['label' => 'Key Passes p/90', 'val' => $format_val($det['key_passes_per_90_overall'] ?? $data['key_passes_per_90_overall'] ?? 0, 'float')],
            ['label' => 'Cross Completion', 'val' => $format_val($det['cross_completion_rate_overall'] ?? 0, 'percent')]
        ],
        'Defensive Actions' => [
            ['label' => 'Tackles Won p/90', 'val' => $format_val($det['tackles_successful_per_90_overall'] ?? 0, 'float')],
            ['label' => 'Interceptions p/90', 'val' => $format_val($det['interceptions_per_90_overall'] ?? 0, 'float')],
            ['label' => 'Clearances p/90', 'val' => $format_val($det['clearances_per_90_overall'] ?? 0, 'float')],
            ['label' => 'Duels Won %', 'val' => $format_val($det['duels_won_percentage_overall'] ?? $det['aerial_duels_won_percentage_overall'] ?? 0, 'percent')]
        ]
    ];

    foreach ($groups as $title => $stats) {
        $valid_stats = [];
        foreach ($stats as $stat) {
            if ($stat['val'] !== 'N/A' && $stat['val'] !== '0.00' && $stat['val'] !== '0' && $stat['val'] !== '0%') {
                $valid_stats[] = $stat;
            }
        }

        if (!empty($valid_stats)) {
            $out .= '<div style="background:'.$c.'; color:'.$tc.'; padding:10px 15px; font-weight:900; text-transform:uppercase; font-family:\'Playfair Display\',serif; border-radius:4px 4px 0 0; margin-top:20px;">'.$title.'</div>';
            $out .= '<div class="fs-stat-grid" style="border:1px solid #eee; border-top:none; border-radius:0 0 4px 4px; padding:20px; background:#fff;">';
            foreach ($valid_stats as $stat) {
                $out .= '<div class="fs-stat-card"><h4>'.$stat['label'].'</h4><div class="fs-stat-val" style="color:'.$c.';">'.$stat['val'].'</div></div>';
            }
            $out .= '</div>';
        }
    }

    $out .= '</div>';
    return $out;
});

