// ==========================================
// 1. PURE-PHP MATCH GETTER
// ==========================================
if (!function_exists('fs_get_matches')) {
function fs_get_matches($type = 'all', $comp_slug = '', $limit = -1, $mw = '', $month = '', $club_id = '', $season = '2026/2027') {
    $args = [
        'post_type'      => ['matches', 'match'],
        'posts_per_page' => -1,
        'post_status'    => 'publish',
    ];

    if ($comp_slug) {
        $slug_dash = str_replace('_', '-', $comp_slug);
        $slug_under = str_replace('-', '_', $comp_slug);
        $terms_to_check = array_unique([$comp_slug, $slug_dash, $slug_under]);
        if (strpos($comp_slug, 'northeast') !== false || strpos($comp_slug, 'north_east') !== false) {
            $terms_to_check = ['t3_northeast', 't3-northeast', 't3_north_east', 't3-north-east'];
        }
        $args['tax_query'] = [['taxonomy' => 'competition', 'field' => 'slug', 'terms' => $terms_to_check, 'include_children' => false]];
    }

    $query = new WP_Query($args);
    $valid = [];
    $seen_matches = []; 

    $short_season = $season;
    if ($season && preg_match('/^(\d{4})\/(\d{4})$/', $season, $m)) {
        $short_season = $m[1] . '/' . substr($m[2], 2);
    }

    foreach ($query->posts as $p) {
        if (isset($seen_matches[$p->ID])) continue;
        $seen_matches[$p->ID] = true;

        if ($season && $season !== 'all') {
            $s_val = get_post_meta($p->ID, 'season', true);
            if ($s_val !== $season && $s_val !== $short_season) continue;
        }

        $hs = get_post_meta($p->ID, 'home_score', true);
        if ($type === 'results' && ($hs === '' || $hs === null)) continue;
        if ($type === 'fixtures' && $hs !== '' && $hs !== null) continue;

        $m_wk = get_post_meta($p->ID, 'match_week', true);
        if ($mw && $m_wk !== $mw) continue;

        $hid_raw = get_post_meta($p->ID, 'home_team', true);
        $aid_raw = get_post_meta($p->ID, 'away_team', true);
        $hid = fs_resolve_id($hid_raw);
        $aid = fs_resolve_id($aid_raw);

        if ($club_id && $hid != $club_id && $aid != $club_id) continue;

        $raw_date = get_post_meta($p->ID, 'date', true);
        if ($month && strpos($raw_date, $month) !== 0) continue;

        $ts = ($raw_date && preg_match('/^\d{8}$/', $raw_date)) ? strtotime($raw_date) : strtotime($p->post_date);

        $comp_name = 'Match';
        $terms = wp_get_post_terms($p->ID, 'competition');
        if (!is_wp_error($terms) && !empty($terms)) $comp_name = $terms[0]->name;

        $raw_time = get_post_meta($p->ID, 'kick_off_time', true);
        $clean_time = ($raw_time && $raw_time !== '00:00:00' && $raw_time !== '00:00') ? date('H:i', strtotime($raw_time)) : 'TBC';

        $valid[] = [
            'ID'   => $p->ID, 
            'hs'   => $hs, 
            'as'   => get_post_meta($p->ID, 'away_score', true), 
            'ts'   => $ts, 
            'time' => $clean_time, 
            'mw'   => $m_wk ?: '1', 
            'hid'  => $hid, 
            'aid'  => $aid, 
            'comp' => $comp_name
        ];
    }

    usort($valid, function($a, $b) use ($type) {
        if ($a['ts'] !== $b['ts']) {
            return ($type === 'fixtures') ? ($a['ts'] - $b['ts']) : ($b['ts'] - $a['ts']);
        }
        return intval($a['mw']) - intval($b['mw']);
    });

    if ($limit > 0) return array_slice($valid, 0, $limit);
    return $valid;
}
}

