// 2. THE IRON-CLAD TABLE BUILDER (STRICT DB WHITELIST)
// ==========================================
if (!function_exists('fs_build_table')) {
function fs_build_table($slug, $season = '2026/2027') {
    // FORCE CACHE BUST: v22.1 ensures the broken 43-team table is obliterated instantly
    $cache_key = 'fs_tbl_v22_1_' . $slug . '_' . sanitize_key($season);
    $cached_teams = get_transient($cache_key);
    if ($cached_teams !== false) return $cached_teams;

    $club_terms = [$slug, str_replace('_', '-', $slug), str_replace('-', '_', $slug)];
    if ($slug === 'thai-league-1') $club_terms = ['t1', 'thai-league-1'];
    if ($slug === 'thai-league-2') $club_terms = ['t2', 'thai-league-2'];
    if ($slug === 'thai-league-3') $club_terms = ['t3', 'thai-league-3'];
    if (strpos($slug, 'northeast') !== false || strpos($slug, 'north_east') !== false) {
        $club_terms = ['t3_northeast', 't3-northeast', 't3_north_east', 't3-north-east'];
    }

    // STRICT WHITELIST: We pull clubs directly from your WP database based on the checkboxes you ticked.
    $clubs = get_posts([
        'post_type'      => 'club',
        'numberposts'    => -1,
        'orderby'        => 'title',
        'order'          => 'ASC',
        'tax_query'      => [[
            'taxonomy'         => 'league',
            'field'            => 'slug',
            'terms'            => $club_terms,
            'include_children' => false
        ]]
    ]);

    $teams = [];
    $valid_club_ids = [];
    foreach ($clubs as $club) {
        $c_name = trim($club->post_title);
        $teams[$c_name] = [
            'id'   => $club->ID, 
            'name' => $c_name, 
            'p'    => 0, 'w' => 0, 'd' => 0, 'l' => 0, 
            'gf'   => 0, 'ga' => 0, 'gd' => 0, 'pts' => 0, 
            'logo' => fs_get_club_logo($club->ID), 
            'form' => []
        ];
        $valid_club_ids[$club->ID] = $c_name;
    }

    // Safety net: If no clubs are registered to this league in WP, return empty.
    if (empty($valid_club_ids)) return [];

    $short_season = $season;
    if (preg_match('/^(\d{4})\/(\d{4})$/', $season, $m)) {
        $short_season = $m[1] . '/' . substr($m[2], 2);
    }

    // Fetch matches for the season
    $matches = get_posts([
        'post_type'      => ['matches', 'match'],
        'posts_per_page' => -1,
        'post_status'    => 'publish',
        'meta_query'     => [
            'relation' => 'OR',
            ['key' => 'season', 'value' => $season, 'compare' => '='],
            ['key' => 'season', 'value' => $short_season, 'compare' => '=']
        ]
    ]);

    foreach ($matches as $p) {
        $hid = fs_resolve_id(get_post_meta($p->ID, 'home_team', true));
        $aid = fs_resolve_id(get_post_meta($p->ID, 'away_team', true));

        // IRON CLAD SHIELD: If BOTH teams are not explicitly checked for this league in your database, ignore the match entirely.
        if (!isset($valid_club_ids[$hid]) || !isset($valid_club_ids[$aid])) continue;

        $h_name = $valid_club_ids[$hid];
        $a_name = $valid_club_ids[$aid];

        $hs_raw = get_post_meta($p->ID, 'home_score', true);
        $as_raw = get_post_meta($p->ID, 'away_score', true);

        if ($hs_raw === '' || $hs_raw === null || $as_raw === '' || $as_raw === null) continue;

        $hs = (int)$hs_raw;
        $as = (int)$as_raw;

        $teams[$h_name]['p']++;  $teams[$a_name]['p']++;
        $teams[$h_name]['gf'] += $hs; $teams[$a_name]['gf'] += $as;
        $teams[$h_name]['ga'] += $as; $teams[$a_name]['ga'] += $hs;
        $teams[$h_name]['gd'] += ($hs - $as); $teams[$a_name]['gd'] += ($as - $hs);

        if ($hs > $as) {
            $teams[$h_name]['pts'] += 3; $teams[$h_name]['w']++; $teams[$a_name]['l']++;
            $teams[$h_name]['form'][] = 'W'; $teams[$a_name]['form'][] = 'L';
        } elseif ($as > $hs) {
            $teams[$a_name]['pts'] += 3; $teams[$a_name]['w']++; $teams[$h_name]['l']++;
            $teams[$h_name]['form'][] = 'L'; $teams[$a_name]['form'][] = 'W';
        } else {
            $teams[$h_name]['pts']++; $teams[$a_name]['pts']++; $teams[$h_name]['d']++; $teams[$a_name]['d']++;
            $teams[$h_name]['form'][] = 'D'; $teams[$a_name]['form'][] = 'D';
        }
    }

    uasort($teams, function($a, $b) { 
        if ($a['pts'] !== $b['pts']) return $b['pts'] - $a['pts'];
        if ($a['gd'] !== $b['gd']) return $b['gd'] - $a['gd'];
        if ($a['gf'] !== $b['gf']) return $b['gf'] - $a['gf'];
        return strcmp($a['name'], $b['name']);
    });

    set_transient($cache_key, $teams, 60); 
    return $teams;
}
}

