    <th title="Won">W</th>
    <th title="Drawn">D</th>
    <th title="Lost">L</th>
    <th title="Goals For">F</th>
    <th title="Goals Against">A</th>
    <th title="Goal Difference">GD</th>
    <th title="Points">Pts</th>
    <th>Form</th>
    </tr>
    </thead>
    <tbody>';

    $pos = 1; 
    foreach ($data as $t) {
        $w = $t['w'] ?? 0; $d = $t['d'] ?? 0; $l = $t['l'] ?? 0;
        $gf = $t['gf'] ?? 0; $ga = $t['ga'] ?? 0; $gd = $t['gd'] ?? 0;
        $pts = $t['pts'] ?? 0; $p = $t['p'] ?? 0;
        $form_data = $t['form'] ?? [];

        $form_html = '<div class="fs-form-guide">';
        $last_5 = array_slice($form_data, -5);
        if (empty($last_5)) {
            $form_html .= '<span style="color:#aaa; font-size:10px;">-</span>';
        } else {
            foreach($last_5 as $res) {
                $class = 'fs-form-' . strtolower($res);
                $form_html .= '<span class="fs-form-dot ' . $class . '" title="' . $res . '"></span>';
            }
        }
        $form_html .= '</div>';

        $out .= '<tr>
        <td class="fs-pos-col">' . $pos . '</td>
        <td class="fs-team-col"><a href="' . esc_url(get_permalink($t['id'])) . '"><img src="' . esc_url($t['logo']) . '" class="fs-tbl-logo">' . esc_html($t['name']) . '</a></td>
        <td>' . $p . '</td>
        <td>' . $w . '</td>
        <td>' . $d . '</td>
        <td>' . $l . '</td>
        <td>' . $gf . '</td>
        <td>' . $ga . '</td>
        <td>' . ($gd > 0 ? '+' : '') . $gd . '</td>
        <td class="fs-pts-col">' . $pts . '</td>
        <td>' . $form_html . '</td>
        </tr>';
        $pos++;
    } 
    $out .= '</tbody></table></div>';
    echo $out;
}
}

