if (!function_exists('fs_get_dynamic_stats')) {
function fs_get_dynamic_stats($type = 'goals') {
    $cache_key = 'fs_t1_stats_v22_' . $type;
    if (false !== ($cached = get_transient($cache_key))) return $cached;

    $post_ids = get_posts([
        'post_type'      => ['matches', 'match'], 
        'posts_per_page' => 150, 
        'post_status'    => 'publish', 
        'fields'         => 'ids',
        'tax_query'      => [['taxonomy' => 'competition', 'field' => 'slug', 'terms' => ['thai-league-1', 't1'], 'include_children' => false]]
    ]);

    $tallies = [];
    foreach ($post_ids as $pid) {
        $events = get_field('match_events', $pid);
        if (!$events || !is_array($events)) continue;
        foreach ($events as $ev) {
            if (strtolower($ev['event_type']) === 'goal') {
                if ($type === 'goals') {
                    $pl_id = fs_resolve_id($ev['primary_player']);
                    if ($pl_id) $tallies[$pl_id] = ($tallies[$pl_id] ?? 0) + 1;
                } elseif ($type === 'assists') {
                    $pl_id = fs_resolve_id($ev['secondary_player']);
                    if ($pl_id) $tallies[$pl_id] = ($tallies[$pl_id] ?? 0) + 1;
                }
            }
        }
    }
    arsort($tallies);
    $top = array_slice($tallies, 0, 10, true);
    set_transient($cache_key, $top, 60); 
    return $top;
}
}

