function fs_custom_match_updater($request) {
    $match_id = (int) $request['id'];
    $data = $request->get_json_params();

    if (!$data) return new WP_Error('no_data', 'No payload received.', array('status' => 400));

    // 1. STATS
    $basic_stats = ['home_possession', 'away_possession', 'home_attempts', 'away_attempts', 'home_on_target', 'away_on_target', 'home_corners', 'away_corners', 'home_fouls', 'away_fouls', 'home_xg', 'away_xg', 'home_formation', 'away_formation'];
    foreach ($basic_stats as $stat) {
        if (isset($data[$stat])) update_field($stat, $data[$stat], $match_id);
    }

    // 2. EVENTS
    if (isset($data['match_events'])) {
        update_field('match_events', $data['match_events'], $match_id);
    }

    // 3. LINEUPS (THE STRICT FIX)
    $lineup_result = 'No lineups sent by Python.';
    if (isset($data['player_stats']) && is_array($data['player_stats'])) {

        $formatted_stats = [];
        foreach ($data['player_stats'] as $row) {
            // FORCE EXACT X-RAY DATA TYPES
            $formatted_stats[] = array(
                'player'         => array( (int) $row['player'] ), 
                'team'           => (string) $row['team'],
                'is_starter'     => filter_var($row['is_starter'], FILTER_VALIDATE_BOOLEAN), 
                'position'       => (string) $row['position'],
                'minutes_played' => (int) $row['minutes_played']
            );
        }

        // Wipe old data
        delete_field('player_stats', $match_id);

        // Dynamically find your secret ACF Field Key so we don't have to guess
        $field = acf_get_field('player_stats');

        if ($field && isset($field['key'])) {
            $success = update_field($field['key'], $formatted_stats, $match_id);
            $lineup_result = $success ? 'SUCCESS via Field Key!' : 'FAILED via Field Key. ACF still rejected it.';
        } else {
            $success = update_field('player_stats', $formatted_stats, $match_id);
            $lineup_result = $success ? 'SUCCESS via Field Name!' : 'FAILED via Field Name. ACF still rejected it.';
        }
    }

    // Send the exact result back to Python
    return rest_ensure_response(array(
        'status' => 'complete',
        'lineup_result' => $lineup_result
    ));
}

