add_shortcode('fs_live_scoreboard', function() {
    $today = wp_date('Ymd'); // FIXED: Native WP timezone date

    // A. Check for matches scheduled for TODAY
    $query = new WP_Query([
        'post_type' => 'matches',
        'posts_per_page' => -1,
        'meta_key' => 'date',
        'meta_query' => [['key' => 'date', 'value' => $today, 'compare' => '=']]
    ]);

    $grouped_matches = [];
    if ($query->have_posts()) {
        while ($query->have_posts()) {
            $query->the_post();
            $pid = get_the_ID();
            $terms = wp_get_post_terms($pid, 'competition');
            $comp_name = (!is_wp_error($terms) && !empty($terms)) ? $terms[0]->name : 'Matches';
            $grouped_matches[$comp_name][] = [
                'ID' => $pid,
                'api_id' => get_field('api_id', $pid),
                'time' => get_field('kick_off_time', $pid) ?: 'TBC',
                'hid' => fs_resolve_id(get_field('home_team', $pid)),
                'aid' => fs_resolve_id(get_field('away_team', $pid))
            ];
        }
        wp_reset_postdata();
    }

    // --- THE DUAL-SORTING ENGINE ---
    if (!empty($grouped_matches)) {

        // 1. Sort Matches inside the Leagues by Kick-Off Time (Earliest First)
        foreach ($grouped_matches as $league => &$matches_array) {
            $sort_times = [];
            foreach ($matches_array as $key => $row) {
                $t = $row['time'];
                $sort_times[$key] = ($t === 'TBC' || empty($t)) ? '23:59' : date('H:i', strtotime($t));
            }
            array_multisort($sort_times, SORT_ASC, SORT_STRING, $matches_array);
        }
        unset($matches_array);

        // 2. Sort the Leagues themselves (T1 Top, then T2, then Cups)
        $order_map = [
            'thai league 1' => 1, 't1' => 1,
            'thai league 2' => 2, 't2' => 2,
            'fa cup' => 3, 'thai fa cup' => 3,
            'league cup' => 4, 'thai league cup' => 4,
            'afc champions league elite' => 5, 'acl elite' => 5,
            'afc champions league two' => 6, 'acl two' => 6,
            'asean club championship' => 7, 'shopee cup' => 7
        ];

        uksort($grouped_matches, function($a, $b) use ($order_map) {
            $weight_a = 99; $weight_b = 99;
            $a_clean = strtolower($a); $b_clean = strtolower($b);
            foreach ($order_map as $k => $v) { 
                if (strpos($a_clean, $k) !== false) $weight_a = min($weight_a, $v); 
                if (strpos($b_clean, $k) !== false) $weight_b = min($weight_b, $v); 
