                    data.forEach(m => {
                        let card = document.querySelector(`.fs-live-card[data-api-id='${m.api_id}']`);
                        if(card) {
                            card.classList.add('active-live');
                            card.querySelector('.fs-live-score-box').innerText = `${m.home_score} - ${m.away_score}`;
                            card.querySelector('.fs-live-score-box').style.color = '#ffd700';
                            let stat = card.querySelector('.fs-live-status');
                            let txt = m.status === 'HT' ? 'HALF TIME' : m.elapsed + "'";
                            stat.innerHTML = `<span class="fs-is-live"><span class="fs-pulse-dot"></span> LIVE: ${txt}</span>`;
                        }
                    });
                }).catch(err => console.log('Waiting for live data...'));
            }

            const timerEl = document.getElementById('fs-timer');
            if (timerEl) {
                const targetTs = parseInt(timerEl.dataset.targetTs);
                if (isNaN(targetTs)) return; 

                const units = timerEl.querySelectorAll('.tm-unit span');

                function updateTimer() {
                    const nowTs = Math.floor(Date.now() / 1000);
                    const diff = targetTs - nowTs;

                    if (diff <= 0) {
                        timerEl.innerHTML = "<h4 style='color:#d93025; font-weight:900; letter-spacing:1px;'>KICKING OFF...</h4>";
                        setTimeout(() => { location.reload(); }, 15000);
                        return;
                    }

                    const d = Math.floor(diff / 86400);
                    const h = Math.floor((diff % 86400) / 3600);
                    const m = Math.floor((diff % 3600) / 60);
                    const s = diff % 60;

                    units[0].innerText = d.toString().padStart(2, '0');
                    units[1].innerText = h.toString().padStart(2, '0');
                    units[2].innerText = m.toString().padStart(2, '0');
                    units[3].innerText = s.toString().padStart(2, '0');
                }
                setInterval(updateTimer, 1000);
                updateTimer();
            }

            if (!timerEl) {
                setInterval(updateLive, 30000);
                updateLive();
            }
        })();
        </script>
    </div>
    <?php
    return ob_get_clean();
});

