    $match_id = get_the_ID();

    // Grab the data
    $h_id = get_field('home_team', $match_id);
    $a_id = get_field('away_team', $match_id);
    if(is_array($h_id)) $h_id = $h_id[0];
    if(is_array($a_id)) $a_id = $a_id[0];

    $home_name = get_the_title($h_id);
    $away_name = get_the_title($a_id);
    $home_score = get_field('home_score', $match_id);
    $away_score = get_field('away_score', $match_id);
    $stadium = get_field('stadium', $match_id) ?: 'TBC';

    // Format Date for Google (ISO 8601)
    $raw_date = get_field('date', $match_id);
    $raw_time = get_field('kick_off_time', $match_id);

    $start_date = '';
    if ($raw_date) {
        $time_str = ($raw_time && $raw_time !== '00:00:00') ? $raw_time : '00:00:00';
        $datetime_str = date('Y-m-d', strtotime($raw_date)) . 'T' . $time_str . '+07:00'; // +07:00 for Bangkok Time
        $start_date = $datetime_str;
    }

    // Build the JSON-LD Array
    $schema = [
        "@context" => "https://schema.org",
        "@type" => "SportsEvent",
        "name" => $home_name . " vs " . $away_name,
        "description" => "Thai football match between " . $home_name . " and " . $away_name,
        "sport" => "Soccer",
        "homeTeam" => [
            "@type" => "SportsTeam",
            "name" => $home_name
        ],
        "awayTeam" => [
            "@type" => "SportsTeam",
            "name" => $away_name
        ],
        "location" => [
            "@type" => "Place",
            "name" => $stadium,
            "address" => "Thailand"
        ]
    ];

    if ($start_date) {
        $schema["startDate"] = $start_date;
    }

    // If match is finished, add the results
    if ($home_score !== '' && $away_score !== '') {
        $schema["eventStatus"] = "https://schema.org/EventFinished";
        $schema["awayTeam"]["description"] = "Score: " . $away_score;
        $schema["homeTeam"]["description"] = "Score: " . $home_score;
    } else {
        $schema["eventStatus"] = "https://schema.org/EventScheduled";
    }

    echo '<script type="application/ld+json">' . json_encode($schema, JSON_UNESCAPED_SLASHES | JSON_PRETTY_PRINT) . '</script>' . "\n";
});

