// 2. AJAX SAVES
add_action('wp_ajax_fs_save_club_hub', function() {
    $cid = intval($_POST['cid']);
    $title = sanitize_text_field($_POST['title']);
    $term_slug = sanitize_text_field($_POST['term']);
    $new_term_name = sanitize_text_field($_POST['new_term']);

    if ($cid > 0) {
        if (!empty($title)) wp_update_post(['ID' => $cid, 'post_title' => $title]);
        $final_term = !empty($new_term_name) ? $new_term_name : $term_slug;
        if (!empty($final_term)) {
            wp_set_object_terms($cid, $final_term, 'league', false);
            wp_set_object_terms($cid, $final_term, 'competition', false);
            wp_set_object_terms($cid, $final_term, 'category', false);
        }
        wp_send_json_success();
    }
    wp_send_json_error();
});

add_action('wp_ajax_fs_trash_club_hub', function() {
    $cid = intval($_POST['cid']);
    if ($cid > 0 && current_user_can('delete_posts')) { wp_trash_post($cid); wp_send_json_success(); }
    wp_send_json_error();
});

// 3. AJAX RECALCULATE TAXONOMY COUNTS
add_action('wp_ajax_fs_recalc_term_counts', function() {
    $taxonomies = ['league', 'competition', 'category'];
    foreach ($taxonomies as $tax) {
        $terms = get_terms(['taxonomy' => $tax, 'hide_empty' => false, 'fields' => 'ids']);
        if (!is_wp_error($terms) && !empty($terms)) {
            wp_update_term_count_now($terms, $tax);
        }
    }
    wp_send_json_success();
});

// 4. AJAX MERGE CLUBS
add_action('wp_ajax_fs_merge_clubs', function() {
    $master_id = intval($_POST['master_id']);
    $slave_id = intval($_POST['slave_id']);

    if (!$master_id || !$slave_id || $master_id === $slave_id) wp_send_json_error('Invalid IDs');

    // A. Update Matches (Home and Away)
    $matches = get_posts(['post_type' => 'matches', 'posts_per_page' => -1, 'fields' => 'ids']);
    foreach ($matches as $mid) {
        $updated = false;

        $h_team = get_post_meta($mid, 'home_team', true);
        $a_team = get_post_meta($mid, 'away_team', true);

        $h_id = is_array($h_team) ? intval($h_team[0]) : intval($h_team);
        $a_id = is_array($a_team) ? intval($a_team[0]) : intval($a_team);

        if ($h_id === $slave_id) { update_post_meta($mid, 'home_team', $master_id); $updated = true; }
        if ($a_id === $slave_id) { update_post_meta($mid, 'away_team', $master_id); $updated = true; }
    }

    // B. Update Players (Current Club)
    $players = get_posts(['post_type' => 'player', 'posts_per_page' => -1, 'fields' => 'ids']);
    foreach ($players as $pid) {
        $club_meta = get_post_meta($pid, 'current_club', true);
        $c_id = is_array($club_meta) ? intval($club_meta[0]) : intval($club_meta);

        if ($c_id === $slave_id) {
            update_post_meta($pid, 'current_club', $master_id);
        }
    }

    // C. Trash the duplicate club
    wp_trash_post($slave_id);
    wp_send_json_success();
});

