/**
 * FOOTBALL SIAM - PRE-IMPORT CLUB AUTO-CREATOR (V3 - Smart Tagging)
 * Parses CSV data, auto-generates missing clubs, and applies parent/child taxonomies (TSP/T3).
 */

add_action('admin_menu', function() {
    add_submenu_page('fs-club-hub', 'Auto-Creator', 'Auto-Creator', 'manage_options', 'fs-club-creator', 'fs_render_club_creator');
});

function fs_render_club_creator() {
    if (isset($_POST['csv_data']) && check_admin_referer('fs_auto_create_clubs')) {
        $csv_data = stripslashes_deep($_POST['csv_data']);
        $lines = explode("\n", $csv_data);
        $created_count = 0;
        $exist_count = 0;
        $log = [];

        // Dynamic column mapping
        $home_idx = -1;
        $away_idx = -1;
        $comp_idx = -1;

        foreach ($lines as $index => $line) {
            $line = trim($line);
            if (empty($line)) continue; // Skip empty lines

            $cols = str_getcsv($line);

            // Read the Header Row to find the correct columns
            if ($index === 0) {
                foreach ($cols as $i => $col_name) {
                    $clean_name = strtolower(trim($col_name));
                    if ($clean_name === 'home team' || $clean_name === 'home_team') $home_idx = $i;
                    if ($clean_name === 'away team' || $clean_name === 'away_team') $away_idx = $i;
                    if ($clean_name === 'match: competitions' || $clean_name === 'competition') $comp_idx = $i;
                }
                continue; // Move to the data rows
            }

            // If we couldn't find the team columns, abort this line
            if ($home_idx === -1 || $away_idx === -1 || !isset($cols[$home_idx]) || !isset($cols[$away_idx])) continue;

            $home_team = trim($cols[$home_idx]);
            $away_team = trim($cols[$away_idx]);
            $competition = isset($cols[$comp_idx]) ? trim($cols[$comp_idx]) : '';

            $teams_to_check = [$home_team, $away_team];

            foreach ($teams_to_check as $team_name) {
                if (empty($team_name)) continue;

                // Check if club already exists
                $existing = get_posts([
                    'post_type' => 'club',
                    'title' => $team_name,
                    'post_status' => 'any',
                    'posts_per_page' => 1
                ]);

                if (empty($existing)) {
                    // Club is missing! Create it.
                    $new_club_id = wp_insert_post([
                        'post_title' => $team_name,
                        'post_type' => 'club',
                        'post_status' => 'publish'
                    ]);

                    if (!is_wp_error($new_club_id)) {
                        // Smart Tagging: Assign region AND parent league
                        if (!empty($competition)) {
                            $terms_to_add = [$competition];
                            // Auto-add parent slugs for T3 and TSP
                            if (strpos($competition, 'tsp_') === 0) $terms_to_add[] = 'tsp';
                            if (strpos($competition, 't3_') === 0) $terms_to_add[] = 'thai-league-3';

                            wp_set_object_terms($new_club_id, $terms_to_add, 'league', false);
                            wp_set_object_terms($new_club_id, $terms_to_add, 'competition', false);
                            wp_set_object_terms($new_club_id, $terms_to_add, 'category', false);
                        }

                        $created_count++;
                        $log[] = "<span style='color:#46b450;'>Created:</span> <strong>{$team_name}</strong>" . (!empty($competition) ? " (Assigned to: {$competition})" : "");
                    }
                } else {
                    $exist_count++;
                }
            }
        }

        echo '<div class="notice notice-success is-dismissible"><p><strong>Success!</strong> Created ' . $created_count . ' new clubs. Skipped ' . $exist_count . ' clubs that already existed.</p></div>';
        if (!empty($log)) {
            echo '<div style="background:#fff; border:1px solid #ccc; padding:15px; max-height:300px; overflow-y:auto; margin-top:15px;">';
            echo implode("<br>", array_unique($log)); 
            echo '</div>';
        }
    }
    ?>
    <div class="wrap">
        <h1 style="font-family: 'Playfair Display', serif;">Pre-Import Club Auto-Creator (V3)</h1>
        <p style="background: #fff; padding: 15px; border-left: 4px solid #0A3B25;">
            Paste your <strong>entire CSV spreadsheet data</strong> below. The script will dynamically find the <code>Home Team</code> and <code>Away Team</code> columns, check your database, create missing clubs, and apply Smart Tagging for TSP and T3 divisions.
        </p>

        <form method="post" action="">
            <?php wp_nonce_field('fs_auto_create_clubs'); ?>
            <textarea name="csv_data" style="width:100%; height:300px; font-family:monospace; padding:10px; background:#fafafa;" placeholder="Paste CSV data here... (Make sure to include the Header Row!)"></textarea>
            <br><br>
            <button type="submit" class="button button-primary button-hero" style="background:#0A3B25; border-color:#0A3B25;">Generate Missing Clubs</button>
        </form>
    </div>
    <?php
}

/**
 * FOOTBALL SIAM - MAGIC MATCH LINKER (Repaired)
 * Parses Match Post Titles to forcefully link ACF Club Relationships.
 * STRICTLY ignores Trashed/Draft clubs.
 */

add_action('admin_menu', function() {
    add_submenu_page('fs-club-hub', 'Match Linker', 'Match Linker', 'manage_options', 'fs-match-linker', 'fs_render_match_linker');
});

function fs_render_match_linker() {
    if (isset($_POST['run_linker']) && check_admin_referer('fs_run_linker_action')) {
        $matches = get_posts([
            'post_type' => 'matches',
            'posts_per_page' => -1,
            'post_status' => 'publish' // Only check published matches
        ]);

        $fixed_count = 0;
        $failed = [];

        foreach ($matches as $m) {
            $title = $m->post_title;

            // Handle both " vs " and " V " variations (case insensitive)
            $separator = stripos($title, ' vs ') !== false ? ' vs ' : (stripos($title, ' V ') !== false ? ' V ' : false);

            if ($separator) {
                // Use regex split to handle case insensitivity gracefully
                $parts = preg_split('/' . $separator . '/i', $title);
                $home_name = trim($parts[0]);
                $away_name = trim($parts[1]);

                // STRICT FIX: Only search 'publish' status. Never grab Trashed clubs.
                $home_club = get_posts(['post_type' => 'club', 'title' => $home_name, 'post_status' => 'publish', 'posts_per_page' => 1, 'fields' => 'ids']);
                $home_id = !empty($home_club) ? $home_club[0] : false;

                $away_club = get_posts(['post_type' => 'club', 'title' => $away_name, 'post_status' => 'publish', 'posts_per_page' => 1, 'fields' => 'ids']);
                $away_id = !empty($away_club) ? $away_club[0] : false;

                if ($home_id && $away_id) {
                    update_post_meta($m->ID, 'home_team', $home_id);
                    update_post_meta($m->ID, 'away_team', $away_id);
                    $fixed_count++;
                } else {
                    $failed[] = "Could not find exact PUBLISHED club match for: <strong>{$title}</strong> (Home: {$home_name} | Away: {$away_name})";
                }
            }
        }

