// 2. The AJAX Handler (Processes the background upload)
add_action('wp_ajax_fs_quick_logo_upload', 'fs_quick_logo_upload_handler');
function fs_quick_logo_upload_handler() {
    check_ajax_referer('fs_logo_nonce', 'security');
    if (!current_user_can('manage_options')) wp_die();

    $club_id = intval($_POST['club_id']);
    if (!$club_id || empty($_FILES['logo_image'])) {
        wp_send_json_error('Missing club ID or image data.');
    }

    if (!function_exists('wp_handle_upload')) {
        require_once(ABSPATH . 'wp-admin/includes/file.php');
    }

    $uploadedfile = $_FILES['logo_image'];

    // Give the file a clean name so your media library doesn't fill up with "image.png"
    $ext = pathinfo($uploadedfile['name'], PATHINFO_EXTENSION) ?: 'png';
    $uploadedfile['name'] = 'club-logo-' . $club_id . '-' . time() . '.' . $ext;

    $upload_overrides = array('test_form' => false);
    $movefile = wp_handle_upload($uploadedfile, $upload_overrides);

    if ($movefile && !isset($movefile['error'])) {
        $image_url = $movefile['url'];

        // Update the ACF Field
        if (function_exists('update_field')) {
            update_field('club_logo_url', $image_url, $club_id);
        } else {
            update_post_meta($club_id, 'club_logo_url', $image_url);
        }

        wp_send_json_success(['url' => $image_url]);
    } else {
        wp_send_json_error($movefile['error']);
    }
}

