            e.preventDefault();

            const clubId = clubSelect.value;
            if (!clubId) {
                alert('Please select a club first!');
                return;
            }

            const items = (e.clipboardData || window.clipboardData).items;
            let imageFile = null;

            for (let i = 0; i < items.length; i++) {
                if (items[i].type.indexOf('image') !== -1) {
                    imageFile = items[i].getAsFile();
                    break;
                }
            }

            if (!imageFile) {
                alert('No image found in your clipboard. Did you copy an image?');
                return;
            }

            // Show preview
            const reader = new FileReader();
            reader.onload = function(event) {
                pasteText.style.display = 'none';
                previewImg.style.display = 'block';
                previewImg.src = event.target.result;
            };
            reader.readAsDataURL(imageFile);

            // Upload via AJAX
            statusDiv.innerHTML = '<span style="color: #0073aa;">Uploading and linking... ⏳</span>';

            const formData = new FormData();
            formData.append('action', 'fs_quick_logo_upload');
            formData.append('security', '<?php echo wp_create_nonce("fs_logo_nonce"); ?>');
            formData.append('club_id', clubId);
            formData.append('logo_image', imageFile);

            fetch('<?php echo admin_url("admin-ajax.php"); ?>', {
                method: 'POST',
                body: formData
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    statusDiv.innerHTML = '<span style="color: #46b450;">✅ Successfully linked!</span>';
                } else {
                    statusDiv.innerHTML = '<span style="color: #d63638;">❌ Upload failed: ' + data.data + '</span>';
                }
            })
            .catch(error => {
                statusDiv.innerHTML = '<span style="color: #d63638;">❌ Connection error.</span>';
                console.error(error);
            });
        });
    });
    </script>
    <?php
}

