'tax_query'      => [['taxonomy' => 'competition', 'field' => 'slug', 'terms' => 'thai-league-1']]
];
$next_matches = get_posts($args);
if (!empty($next_matches)) {
return get_post_meta($next_matches[0]->ID, 'match_week', true);
}
return false;
}
}

add_action('wp_ajax_fs_save_predictions', 'fs_handle_prediction_submission');
function fs_handle_prediction_submission() {
check_ajax_referer('fs_predict_nonce', 'security');
$lang = fs_get_current_lang();

if (!is_user_logged_in()) {
wp_send_json_error(fs_get_text('err_login', $lang));
wp_die();
}

$current_user = wp_get_current_user();
$matchweek_num = isset($_POST['matchweek_num']) ? intval($_POST['matchweek_num']) : 0;
$predictions = isset($_POST['predictions']) ? $_POST['predictions'] : [];

if (!$matchweek_num || empty($predictions)) {
wp_send_json_error(fs_get_text('err_invalid', $lang));
wp_die();
}

$existing = get_posts([
'post_type'  => 'fs_prediction',
'author'     => $current_user->ID,
'meta_query' => [['key' => 'match_week', 'value' => $matchweek_num, 'compare' => '=']]
]);

if (!empty($existing)) {
wp_send_json_error(sprintf(fs_get_text('err_already', $lang), $matchweek_num));
wp_die();
}

$post_title = $current_user->user_login . ' - Matchweek ' . $matchweek_num . ' Predictions';
$post_id = wp_insert_post([
'post_title'  => $post_title,
'post_type'   => 'fs_prediction',
'post_status' => 'publish',
'post_author' => $current_user->ID
]);

if ($post_id) {
update_post_meta($post_id, 'match_week', $matchweek_num);
update_post_meta($post_id, 'prediction_month', date('Y-m'));
update_post_meta($post_id, 'user_lang', $lang); 

foreach ($predictions as $match_id => $scores) {
$mid = intval($match_id);
update_post_meta($post_id, 'match_' . $mid . '_home_guess', intval($scores['home']));
update_post_meta($post_id, 'match_' . $mid . '_away_guess', intval($scores['away']));
}

update_post_meta($post_id, 'status', 'pending'); 
wp_send_json_success(sprintf(fs_get_text('succ_lock', $lang), $matchweek_num));
} else {
wp_send_json_error(fs_get_text('err_db', $lang));
}
wp_die();
}

