function fs_render_predictor_hub() {
if (!current_user_can('manage_options')) return;

echo '<div class="wrap" style="font-family: \'Lato\', sans-serif;">';
echo '<h1 style="font-family: \'Playfair Display\', serif; font-weight: 900; font-size: 32px; margin-bottom: 20px;">Predictor Grader</h1>';

if (isset($_POST['grade_mw']) && isset($_POST['_wpnonce']) && wp_verify_nonce($_POST['_wpnonce'], 'fs_grade_mw')) {
$mw_to_grade = intval($_POST['grade_mw']);

$predictions = get_posts([
'post_type'      => 'fs_prediction',
'posts_per_page' => -1,
'meta_query'     => [
'relation' => 'AND',
['key' => 'match_week', 'value' => $mw_to_grade, 'compare' => '='],
['key' => 'status', 'value' => 'pending', 'compare' => '=']
]
]);

if (empty($predictions)) {
echo '<div class="notice notice-warning is-dismissible"><p>No pending predictions found for Matchweek ' . $mw_to_grade . '.</p></div>';
} else {
$graded_count = 0;

add_action('phpmailer_init', 'fs_predictor_smtp');

foreach ($predictions as $pred) {
$author_id = $pred->post_author;
$total_points = 0;
$pred_meta = get_post_meta($pred->ID);
$u_lang = get_post_meta($pred->ID, 'user_lang', true) ?: 'en'; 

$breakdown_html = '<table style="width:100%; border-collapse:collapse; font-size:12px; margin-top:10px; background:#fff;">';
$breakdown_html .= '<tr style="background:#0A3B25; color:#fff; text-transform:uppercase;">';
$breakdown_html .= '<th style="padding:10px; text-align:left;">' . fs_get_text('match', $u_lang) . '</th>';
$breakdown_html .= '<th style="padding:10px; text-align:center;">' . fs_get_text('pick', $u_lang) . '</th>';
$breakdown_html .= '<th style="padding:10px; text-align:center;">' . fs_get_text('actual', $u_lang) . '</th>';
$breakdown_html .= '<th style="padding:10px; text-align:center;">' . fs_get_text('pts', $u_lang) . '</th></tr>';

$email_rows = '';

foreach ($pred_meta as $key => $values) {
if (strpos($key, 'match_') === 0 && strpos($key, '_home_guess') !== false) {
$match_id = str_replace(['match_', '_home_guess'], '', $key);
$away_key = 'match_' . $match_id . '_away_guess';

if (isset($pred_meta[$away_key])) {
$guess_h = intval($values[0]);
$guess_a = intval($pred_meta[$away_key][0]);

$actual_h = get_post_meta($match_id, 'home_score', true);
$actual_a = get_post_meta($match_id, 'away_score', true);

$hid_raw = get_post_meta($match_id, 'home_team', true);
$aid_raw = get_post_meta($match_id, 'away_team', true);
$hid = fs_resolve_id(is_string($hid_raw) && is_serialized($hid_raw) ? unserialize($hid_raw) : $hid_raw);
$aid = fs_resolve_id(is_string($aid_raw) && is_serialized($aid_raw) ? unserialize($aid_raw) : $aid_raw);
$home_name = $hid ? get_the_title($hid) : 'Home';
$away_name = $aid ? get_the_title($aid) : 'Away';
$match_name = $home_name . ' vs ' . $away_name;

if ($actual_h !== '' && $actual_a !== '') {
$actual_h = intval($actual_h);
$actual_a = intval($actual_a);
$pts = 0;

if ($guess_h === $actual_h && $guess_a === $actual_a) {
$pts = 3;
$total_points += 3;
} else {
$guess_result = ($guess_h > $guess_a) ? 'H' : (($guess_a > $guess_h) ? 'A' : 'D');
$actual_result = ($actual_h > $actual_a) ? 'H' : (($actual_a > $actual_h) ? 'A' : 'D');
if ($guess_result === $actual_result) {
$pts = 1;
$total_points += 1;
}
}

$color = ($pts == 3) ? '#28a745' : (($pts == 1) ? '#ffc107' : '#dc3545');

$row = '<tr>';
$row .= '<td style="padding:10px; border-bottom:1px solid #eee;">' . esc_html($match_name) . '</td>';
$row .= '<td style="padding:10px; border-bottom:1px solid #eee; text-align:center;">' . $guess_h . ' - ' . $guess_a . '</td>';
$row .= '<td style="padding:10px; border-bottom:1px solid #eee; text-align:center;">' . $actual_h . ' - ' . $actual_a . '</td>';
$row .= '<td style="padding:10px; border-bottom:1px solid #eee; text-align:center; font-weight:bold; color:' . $color . ';">' . $pts . '</td>';
$row .= '</tr>';

$breakdown_html .= $row;
$email_rows .= $row;
}
}
}
}

$breakdown_html .= '</table>';
update_post_meta($pred->ID, '_fs_breakdown_html', $breakdown_html);

$user = get_userdata($author_id);
if ($total_points > 0) {
$month = get_post_meta($pred->ID, 'prediction_month', true) ?: date('Y-m');

$score_post_id = wp_insert_post([
'post_title'  => $user->user_login . ' - MW ' . $mw_to_grade . ' Predictor Points',
'post_type'   => 'fs_score',
'post_status' => 'publish',
'post_author' => $author_id
]);

if ($score_post_id) {
update_post_meta($score_post_id, 'scouter_score', $total_points);
update_post_meta($score_post_id, 'scouter_month', $month);
update_post_meta($score_post_id, 'score_source', 'predictor'); 
}
}

$to = $user->user_email;
$subject = sprintf(fs_get_text('email_subj', $u_lang), $mw_to_grade);
$email_html = '<div style="font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: auto;">';
$email_html .= '<h2 style="color: #0A3B25; font-family: Georgia, serif;">' . fs_get_text('email_title', $u_lang) . '</h2>';
$email_html .= '<p>Hi ' . esc_html($user->display_name) . ',</p>';
$email_html .= '<p>' . fs_get_text('email_intro', $u_lang) . '</p>';
$email_html .= '<table style="width:100%; border-collapse:collapse; font-size:14px; margin-top:20px;">';
$email_html .= '<tr style="background:#0A3B25; color:#fff; text-transform:uppercase;">';
$email_html .= '<th style="padding:10px; text-align:left;">' . fs_get_text('match', $u_lang) . '</th>';
$email_html .= '<th style="padding:10px; text-align:center;">' . fs_get_text('pick', $u_lang) . '</th>';
$email_html .= '<th style="padding:10px; text-align:center;">' . fs_get_text('actual', $u_lang) . '</th>';
$email_html .= '<th style="padding:10px; text-align:center;">' . fs_get_text('pts', $u_lang) . '</th></tr>';
$email_html .= $email_rows;
$email_html .= '</table>';
$email_html .= '<p style="margin-top:20px;">' . sprintf(fs_get_text('email_scored', $u_lang), $total_points) . '</p>';
$email_html .= '<p>' . fs_get_text('email_cheers', $u_lang) . '</p>';
$email_html .= '</div>';

wp_mail($to, $subject, $email_html, ['Content-Type: text/html; charset=UTF-8']);

update_post_meta($pred->ID, 'status', 'graded');
update_post_meta($pred->ID, 'points_awarded', $total_points);
$graded_count++;
}

remove_action('phpmailer_init', 'fs_predictor_smtp');

echo '<div class="notice notice-success is-dismissible"><p><strong>Success!</strong> Successfully graded ' . $graded_count . ' prediction(s) for Matchweek ' . $mw_to_grade . ', updated the global leaderboard, and dispatched the bilingual result emails.</p></div>';
}
}

echo '<div style="background: #fff; padding: 20px; border: 1px solid #ccc; border-radius: 8px; max-width: 500px; box-shadow: 0 2px 5px rgba(0,0,0,0.05);">';
echo '<p style="font-size: 14px; margin-bottom: 20px;">Once a Matchweek is completely finished and you have entered all the final scores into your T1 database, select the Matchweek below and click Grade. The system will automatically calculate points and push them to the global leaderboard.</p>';
echo '<form method="POST">';
wp_nonce_field('fs_grade_mw');
echo '<select name="grade_mw" style="padding: 8px; font-size: 14px; border-radius: 4px; margin-right: 10px;">';
for ($i = 1; $i <= 30; $i++) {
echo '<option value="' . $i . '">Matchweek ' . $i . '</option>';
}
echo '</select>';
echo '<button type="submit" class="button button-primary" style="background: #0A3B25; border-color: #072f1e;">Grade Predictions & Send Emails</button>';
echo '</form>';
echo '</div>';
echo '</div>';
}

