<script>
document.addEventListener('DOMContentLoaded', function() {
const uid = "<?php echo $uid; ?>";
const gameID = "<?php echo $game_number_display; ?>";
const answerFull = <?php echo json_encode(strtolower($p_name)); ?>;
const answerLast = <?php echo json_encode(strtolower($ans_last)); ?>;
const answerNick = <?php echo json_encode(strtolower($ans_nick)); ?>;
const playerData = <?php echo json_encode($player_data_json); ?>;
const ajaxUrl = "<?php echo $ajax_url; ?>";
const nonce = "<?php echo $nonce; ?>";

let timeRemaining = <?php echo intval($seconds_until_midnight); ?>;
let score = 100;
let gameActive = true;

const scoreEl = document.getElementById('fs-score-' + uid);
const input = document.getElementById('fs-guess-input-' + uid);
const list = document.getElementById('fs-autocomplete-' + uid);
const submitBtn = document.getElementById('fs-guess-submit-btn-' + uid);
const wrap = document.getElementById('fs-guess-wrap-' + uid);
const feedback = document.getElementById('fs-feedback-' + uid);
const endScreen = document.getElementById('fs-end-' + uid);
const resultTitle = document.getElementById('fs-result-title-' + uid);
const countdownEl = document.getElementById('fs-countdown-' + uid);
const twitterLink = document.getElementById('fs-twitter-link-' + uid);
const saveBtn = document.getElementById('fs-save-btn-' + uid);
const shareBtn = document.getElementById('fs-share-btn-' + uid);
const tiles = document.querySelectorAll('.fs-tile-' + uid);

function initGame() {
const lastPlayed = localStorage.getItem('fs_scout_date');
if(lastPlayed === gameID) {
const savedScore = parseInt(localStorage.getItem('fs_scout_score')) || 0;
const winStatus = localStorage.getItem('fs_scout_status') === 'win';
score = savedScore;
if(scoreEl) scoreEl.innerText = savedScore;
endGame(winStatus, true);
}
}
initGame();

function updateCountdown() {
if (timeRemaining <= 0) {
if(countdownEl) countdownEl.innerText = "NEW TARGET LIVE! REFRESH PAGE";
return;
}
let h = Math.floor(timeRemaining / 3600);
let m = Math.floor((timeRemaining % 3600) / 60);
let s = timeRemaining % 60;
if(countdownEl) countdownEl.innerText = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
timeRemaining--;
}
setInterval(updateCountdown, 1000);
updateCountdown();

tiles.forEach(function(tile) {
tile.addEventListener('click', function() {
if(!gameActive || this.classList.contains('revealed')) return;
const cost = parseInt(this.getAttribute('data-cost'));
score -= cost;
if(score < 0) score = 0;
if(scoreEl) scoreEl.innerText = score;
this.classList.add('revealed');
if(score <= 0) endGame(false);
});
});

if(input) {
input.addEventListener('input', function() {
if (!gameActive) return;
const val = this.value.toLowerCase();
list.innerHTML = '';
if (val.length < 2) { list.style.display = 'none'; return; }
const matches = playerData.filter(p => p.full.toLowerCase().includes(val) || (p.nick && p.nick.toLowerCase().includes(val)) || (p.last && p.last.toLowerCase().includes(val))).slice(0, 6);
if (matches.length > 0) {
list.style.display = 'block';
matches.forEach(p => {
const div = document.createElement('div');
div.className = 'fs-autocomplete-item';
div.innerText = p.nick ? p.full + " (" + p.nick + ")" : p.full;
div.onclick = () => { input.value = p.full; list.style.display = 'none'; };
list.appendChild(div);
});
} else { list.style.display = 'none'; }
});
input.addEventListener("keypress", function(event) {
if (event.key === "Enter") { event.preventDefault(); makeGuess(); }
});
}

document.addEventListener('click', function(e) {
if (e.target !== input && e.target !== list && list) list.style.display = 'none';
});

function makeGuess() {
if(!gameActive || !input) return;
const val = input.value.toLowerCase().trim();
if(val === "") return;
const isMatch = (val === answerFull || (answerLast !== "" && val === answerLast) || (answerNick !== "" && answerNick.includes(val) && val.length >= 3));

if(isMatch) { 
endGame(true); 
} else {
score -= 10;
if (score < 0) score = 0; 
if(scoreEl) scoreEl.innerText = score;
if(feedback) {
feedback.innerText = "❌ INCORRECT GUESS (-10 PTS)";
feedback.style.color = "#d93025";
}
input.style.transform = "translateX(-10px)";
setTimeout(() => input.style.transform = "translateX(10px)", 100);
setTimeout(() => input.style.transform = "translateX(-10px)", 200);
setTimeout(() => input.style.transform = "translateX(0)", 300);
input.value = "";
if(score <= 0) endGame(false);
}
}

if(submitBtn) submitBtn.addEventListener('click', makeGuess);

function endGame(win, wasLocked = false) {
gameActive = false;
if(input) input.disabled = true;
if(submitBtn) submitBtn.disabled = true;
if(wrap) wrap.style.display = 'none';
if(feedback) feedback.style.display = 'none';
if(endScreen) endScreen.style.display = 'block';

if(resultTitle) {
if (wasLocked) {
resultTitle.innerText = win ? "SCOUTED (ALREADY PLAYED)" : "FAILED (ALREADY PLAYED)";
resultTitle.style.color = win ? "#0A3B25" : "#d93025";
} else {
resultTitle.innerText = win ? "Target Found" : "Target Escaped";
resultTitle.style.color = win ? "#0A3B25" : "#d93025";
}
}

if(!wasLocked) {
localStorage.setItem('fs_scout_date', gameID);
localStorage.setItem('fs_scout_score', score);
localStorage.setItem('fs_scout_status', win ? 'win' : 'lose');
}

tiles.forEach(t => t.classList.add('revealed'));
const text = "The Siam Scout #" + gameID + " \nScore: " + score + "/100\n\nCan you scout today's player? 👉 footballsiam.com/siam-scout/";
if(twitterLink) twitterLink.href = "https://twitter.com/intent/tweet?text=" + encodeURIComponent(text);
}

if(shareBtn) {
shareBtn.addEventListener('click', function() {
const text = "The Siam Scout #" + gameID + " \nScore: " + score + "/100\n\nCan you scout today's player? 👉 footballsiam.com/siam-scout/";
navigator.clipboard.writeText(text).then(() => alert("Score copied to clipboard!"));
});
}

if(saveBtn) {
saveBtn.addEventListener('click', function() {
saveBtn.innerText = "SAVING...";
saveBtn.disabled = true;

const formData = new FormData();
formData.append("action", "fs_save_scouter_score");
formData.append("security", nonce);
formData.append("score", score);

fetch(ajaxUrl, { method: "POST", body: formData })
.then(res => res.json())
.then(data => {
if(data.success) {
saveBtn.innerText = "SAVED!";
saveBtn.style.background = "#0A3B25";
setTimeout(() => { window.location.reload(); }, 1000);
} else {
alert("Error: " + data.data);
saveBtn.innerText = "SAVE TO LEADERBOARD";
saveBtn.disabled = false;
}
})
.catch(err => {
alert("Connection error. Try again.");
saveBtn.innerText = "SAVE TO LEADERBOARD";
saveBtn.disabled = false;
});
});
}
}); 
</script>
<?php
return ob_get_clean();
});

add_action('wp_ajax_fs_save_scouter_score', 'fs_save_scouter_score_handler');
function fs_save_scouter_score_handler() {
check_ajax_referer('fs_scouter_nonce', 'security');
if (!is_user_logged_in()) { wp_send_json_error('You must be logged in.'); wp_die(); }

$score = intval($_POST['score']);
$user = wp_get_current_user();
$month = date('Y-m');
$today = date('Y-m-d');

$existing = get_posts([
'post_type'  => 'fs_score',
'author'     => $user->ID,
'title'      => $user->user_login . ' - ' . $today,
'post_status'=> 'publish'
]);

if (!empty($existing)) { wp_send_json_error('You have already saved your score today!'); wp_die(); }

$post_id = wp_insert_post([
'post_title'  => $user->user_login . ' - ' . $today,
'post_type'   => 'fs_score',
'post_status' => 'publish',
'post_author' => $user->ID
]);

if ($post_id) {
update_post_meta($post_id, 'scouter_score', $score);
update_post_meta($post_id, 'scouter_month', $month);
update_post_meta($post_id, 'score_source', 'scout');
wp_send_json_success('Score Saved');
} else {
wp_send_json_error('Database error.');
}
wp_die();
}

