add_action('save_post', function($post_id) {
if (!isset($_POST['fs_gs_nonce']) || !wp_verify_nonce($_POST['fs_gs_nonce'], 'fs_gs_save_nonce')) return;
if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) return;
if (!current_user_can('edit_post', $post_id)) return;

$is_global = isset($_POST['global_scout']) ? '1' : '0';
if ($is_global === '1') {
update_post_meta($post_id, 'global_scout', '1');
} else {
delete_post_meta($post_id, 'global_scout');
}

if (isset($_POST['gs_league'])) update_post_meta($post_id, 'gs_league', sanitize_text_field($_POST['gs_league']));
if (isset($_POST['gs_club'])) update_post_meta($post_id, 'gs_club', sanitize_text_field($_POST['gs_club']));
});

add_action('wp_ajax_fs_save_global_scout', 'fs_handle_global_scout_save');
function fs_handle_global_scout_save() {
check_ajax_referer('fs_global_scout_nonce', 'security');
if (!is_user_logged_in()) { wp_send_json_error('Log in required.'); wp_die(); }

$current_user = wp_get_current_user();
$score = intval($_POST['score']);
$today = date('Y-m-d');
$month = date('Y-m');

$existing = get_posts([
'post_type'  => 'fs_score',
'author'     => $current_user->ID,
'title'      => $current_user->user_login . ' - Global Scout - ' . $today,
'post_status'=> 'publish'
]);

if (!empty($existing)) { wp_send_json_error('You have already scouted the globe today!'); wp_die(); }

$post_id = wp_insert_post([
'post_title'  => $current_user->user_login . ' - Global Scout - ' . $today,
'post_type'   => 'fs_score',
'post_status' => 'publish',
'post_author' => $current_user->ID
]);

if ($post_id) {
update_post_meta($post_id, 'scouter_score', $score);
update_post_meta($post_id, 'scouter_month', $month);
update_post_meta($post_id, 'score_source', 'global_scout'); 
wp_send_json_success('Global Scout Score Saved!');
} else { wp_send_json_error('Database error.'); }
wp_die();
}

