$out .= '<script>
document.addEventListener("DOMContentLoaded", function() {
const db = '.json_encode($players).';
const targetIndex = '.$target_index.';
const target = db[targetIndex];
const uid = "'.$uid.'";
const nonce = "'.wp_create_nonce('fs_global_scout_nonce').'";

let guesses = 0;
const maxGuesses = 6;
let gameActive = true;
let shareGrid = "FC Siam Global Scout #" + '.$day_seed.' + "\n\n";
const scoreMap = [100, 85, 70, 50, 30, 15]; 

const input = document.getElementById("gs-input-" + uid);
const acList = document.getElementById("gs-ac-" + uid);
const grid = document.getElementById("gs-grid-" + uid);
const gameArea = document.getElementById("gs-game-area-" + uid);
const endScreen = document.getElementById("gs-end-" + uid);
const endTitle = document.getElementById("gs-end-title-" + uid);
const endPlayer = document.getElementById("gs-end-player-" + uid);
const endImg = document.getElementById("gs-end-img-" + uid);
const endBio = document.getElementById("gs-end-bio-" + uid);
const btnShare = document.getElementById("gs-share-" + uid);
const btnSave = document.getElementById("gs-save-" + uid);

const savedDay = localStorage.getItem("gs_date");
if (savedDay === "'.$day_seed.'") {
    endGame(localStorage.getItem("gs_status") === "win", true);
}

input.addEventListener("input", function() {
    if (!gameActive) return;
    const val = this.value.toLowerCase();
    acList.innerHTML = "";
    if (val.length < 2) { acList.style.display = "none"; return; }

    const matches = db.filter(p => p.name.toLowerCase().includes(val)).slice(0, 6);
    if (matches.length > 0) {
        acList.style.display = "block";
        matches.forEach(p => {
            const div = document.createElement("div");
            div.className = "gs-ac-item";
            div.innerText = p.name;
            div.onclick = () => makeGuess(p);
            acList.appendChild(div);
        });
    } else { acList.style.display = "none"; }
});

document.addEventListener("click", e => { if (e.target !== input) acList.style.display = "none"; });

function makeGuess(player) {
    if (!gameActive) return;
    input.value = "";
    acList.style.display = "none";
    if (guesses === 0) grid.innerHTML = ""; 

    guesses++;

    const isNat = player.nat === target.nat;
    const isLge = player.league === target.league;
    const isClub = player.club === target.club;
    const isPos = player.pos === target.pos;

    let ageStatus = "grey";
    let ageText = player.age;
    if (player.age === target.age) { ageStatus = "green"; }
    else if (Math.abs(player.age - target.age) <= 2) { 
        ageStatus = "yellow"; 
        ageText += (player.age > target.age) ? " ⬇" : " ⬆"; 
    } else {
        ageText += (player.age > target.age) ? " ⬇" : " ⬆";
    }

    const row = document.createElement("div");
    row.className = "gs-row";
    row.innerHTML += `<div class="gs-tile gs-grey"><span>PLAYER</span>${player.name}</div>`;
    row.innerHTML += `<div class="gs-tile ${isNat ? "gs-green" : "gs-grey"}"><span>NAT</span>${player.nat}</div>`;
    row.innerHTML += `<div class="gs-tile ${isLge ? "gs-green" : "gs-grey"}"><span>LEAGUE</span>${player.league}</div>`;
    row.innerHTML += `<div class="gs-tile ${isClub ? "gs-green" : "gs-grey"}"><span>CLUB</span>${player.club}</div>`;
    row.innerHTML += `<div class="gs-tile ${isPos ? "gs-green" : "gs-grey"}"><span>POS</span>${player.pos}</div>`;
    row.innerHTML += `<div class="gs-tile gs-${ageStatus}"><span>AGE</span>${ageText}</div>`;
    grid.prepend(row);

    shareGrid += (isNat?"🟩":"⬛") + (isLge?"🟩":"⬛") + (isClub?"🟩":"⬛") + (isPos?"🟩":"⬛") + (ageStatus==="green"?"🟩":(ageStatus==="yellow"?"🟨":"⬛")) + "\n";

    if (player.name === target.name) { endGame(true, false); } else if (guesses >= maxGuesses) { endGame(false, false); }
}

function endGame(win, wasLocked) {
    gameActive = false;
    input.disabled = true;
    input.placeholder = "SCOUTING COMPLETE";

    setTimeout(() => {
        endScreen.style.display = "block";
        endTitle.innerText = win ? "Target Identified!" : "Target Escaped";
        endTitle.style.color = win ? "#0A3B25" : "#d93025";
        endPlayer.innerText = target.name;
        if (target.bio) { endBio.innerText = \'"\' + target.bio + \'"\'; }
        if (target.photo && target.photo.trim() !== "") {
            endImg.src = target.photo;
            endImg.style.display = "block";
        }
    }, 500);

    const finalScore = win ? scoreMap[guesses - 1] : 0;
    shareGrid += "\n" + (win ? guesses : "X") + "/" + maxGuesses + " - " + finalScore + " PTS";

    if (!wasLocked) {
        localStorage.setItem("gs_date", "'.$day_seed.'");
        localStorage.setItem("gs_status", win ? "win" : "lose");
        localStorage.setItem("gs_score", finalScore);
        localStorage.setItem("gs_guesses", guesses);
    }
}

btnShare.addEventListener("click", () => {
    navigator.clipboard.writeText(shareGrid).then(() => {
        btnShare.innerText = "COPIED!";
        setTimeout(() => btnShare.innerText = "Copy Result 📋", 2000);
    });
});

btnSave.addEventListener("click", () => {
    btnSave.disabled = true;
    btnSave.innerText = "SAVING...";

    const pts = parseInt(localStorage.getItem("gs_score")) || 0;
    const formData = new URLSearchParams();
    formData.append("action", "fs_save_global_scout");
    formData.append("security", nonce);
    formData.append("score", pts);

    fetch("'.admin_url('admin-ajax.php').'", { method: "POST", body: formData })
    .then(r => r.json()).then(data => {
        if(data.success) {
            btnSave.innerText = "POINTS SECURED!";
            btnSave.style.background = "#50c8b4";
        } else {
            alert(data.data);
            btnSave.disabled = false;
            btnSave.innerText = "Save Points to Leaderboard";
        }
    }).catch(() => {
        alert("Error connecting.");
        btnSave.disabled = false;
        btnSave.innerText = "Save Points to Leaderboard";
    });
});

});
</script>';

$out .= '</div>';
return $out;
});

