function fs_render_global_scout_hub() {
if (!current_user_can('manage_options')) return;
$page_url = admin_url('admin.php?page=fs-global-scout-hub');

if (isset($_GET['add_global']) && isset($_GET['_wpnonce']) && wp_verify_nonce($_GET['_wpnonce'], 'fs_global_toggle')) {
update_post_meta(intval($_GET['add_global']), 'global_scout', '1');
echo '<div class="notice notice-success is-dismissible"><p><strong>Success!</strong> Player drafted into Global Scout.</p></div>';
}
if (isset($_GET['remove_global']) && isset($_GET['_wpnonce']) && wp_verify_nonce($_GET['_wpnonce'], 'fs_global_toggle')) {
delete_post_meta(intval($_GET['remove_global']), 'global_scout');
echo '<div class="notice notice-info is-dismissible"><p>Player removed from Global Scout.</p></div>';
}

$active_args = ['post_type' => 'player', 'posts_per_page' => -1, 'meta_query' => [['key' => 'global_scout', 'value' => '1', 'compare' => '=']], 'orderby' => 'title', 'order' => 'ASC'];
$active_query = new WP_Query($active_args);
$total_in_game = $active_query->found_posts; 

$action_required = [];
$ready_players = [];

if ($active_query->have_posts()) {
while ($active_query->have_posts()) {
$active_query->the_post();
$pid = get_the_ID();
$missing = [];

if (empty(get_post_meta($pid, 'gs_league', true))) $missing[] = 'League';
if (empty(get_post_meta($pid, 'gs_club', true))) $missing[] = 'Club';
if (empty(get_post_meta($pid, 'ss_short_bio', true))) $missing[] = 'Bio';

$photo = get_post_meta($pid, 'ss_scout_photo', true);
if (is_array($photo) && isset($photo['url'])) $photo = $photo['url'];
if (is_numeric($photo)) $photo = wp_get_attachment_url($photo);
if (!$photo && !get_field('player_photo_url', $pid) && !get_the_post_thumbnail_url($pid)) $missing[] = 'Photo';

$remove_url = wp_nonce_url(add_query_arg('remove_global', $pid, $page_url), 'fs_global_toggle');

if (!empty($missing)) {
$action_required[] = ['id' => $pid, 'title' => get_the_title(), 'missing' => implode(', ', $missing), 'edit_link' => get_edit_post_link($pid), 'remove_link' => $remove_url];
} else {
$ready_players[] = ['id' => $pid, 'title' => get_the_title(), 'edit_link' => get_edit_post_link($pid), 'remove_link' => $remove_url];
}
}
wp_reset_postdata();
}

$pending_args = ['post_type' => 'player', 'posts_per_page' => -1, 'orderby' => 'title', 'order' => 'ASC', 'meta_query' => [['relation' => 'OR', ['key' => 'global_scout', 'compare' => 'NOT EXISTS'], ['key' => 'global_scout', 'value' => '1', 'compare' => '!=']]]];
$pending_query = new WP_Query($pending_args);
$pending_count = $pending_query->found_posts;

echo '<div class="wrap" style="font-family: \'Lato\', sans-serif;">';
echo '<h1 style="font-family: \'Playfair Display\', serif; font-weight: 900; font-size: 32px; margin-bottom: 20px;">Global Scout Hub</h1>';
echo '<div style="display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap;">';

echo '<div style="flex: 1; min-width: 300px; background: #fffcfc; padding: 20px; border: 1px solid #ffcccc; border-radius: 8px; box-shadow: 0 2px 5px rgba(217,48,37,0.1);">';
echo '<div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #ffcccc; padding-bottom: 10px; margin-bottom: 15px;">';
echo '<h2 style="margin:0; font-size: 18px; color: #d93025; font-weight: 900;">🚨 Missing Clues</h2>';
echo '<span style="background: #d93025; color: #fff; padding: 3px 10px; border-radius: 15px; font-weight: bold; font-size: 12px;">' . count($action_required) . ' Incomplete</span>';
echo '</div><div style="max-height: 500px; overflow-y: auto; padding-right: 5px;">';
if (!empty($action_required)) {
foreach ($action_required as $req) {
echo '<div style="background: #fff; border: 1px solid #eee; padding: 12px; margin-bottom: 10px; border-radius: 4px; border-left: 4px solid #d93025;">';
