/**
 * FOOTBALL SIAM - SEASON ROLLOVER & PROMOTION MANAGER (v1.1)
 * Clears transients, resets player season tallies, and updates club division taxonomies.
 * Filters out foreign/other clubs from the dropdown to prevent clutter.
 */

add_action('admin_menu', function() {
    add_submenu_page(
        'fs-scout-hub',
        'Promotion & Reset',
        'Promotion & Reset',
        'manage_options',
        'fs-promotion-reset',
        'fs_render_promotion_reset_page'
    );
});

function fs_render_promotion_reset_page() {
    if (!current_user_can('manage_options')) return;

    $message = '';

    // --- HANDLE PROMOTION / RELEGATION & TAXONOMY UPDATES ---
    if (isset($_POST['fs_apply_promotions']) && check_admin_referer('fs_promo_action')) {
        $club_id = intval($_POST['promo_club_id']);
        $target_league = sanitize_text_field($_POST['target_league_slug']);

        if ($club_id && $target_league) {
            // Update the 'league' taxonomy on the club post
            wp_set_object_terms($club_id, $target_league, 'league', false);
            // Also update 'competition' taxonomy if used on club posts
            wp_set_object_terms($club_id, $target_league, 'competition', false);

            $message = '<div class="notice notice-success is-dismissible"><p><strong>Updated:</strong> ' . esc_html(get_the_title($club_id)) . ' moved to <code>' . esc_html($target_league) . '</code> taxonomy.</p></div>';
        }
    }

    // --- HANDLE FULL MASTER RESET ---
    if (isset($_POST['fs_run_master_reset']) && check_admin_referer('fs_reset_action')) {
        global $wpdb;

        // 1. Flush all Football Siam transients (Tables, Stats, Predictors)
        $wpdb->query("DELETE FROM {$wpdb->options} WHERE option_name LIKE '_transient_fs_%' OR option_name LIKE '_transient_timeout_fs_%'");

        // 2. Reset Player Season Meta Fields
        $players = get_posts([
            'post_type'      => 'player',
            'posts_per_page' => -1,
            'fields'         => 'ids'
        ]);

        $reset_count = 0;
        foreach ($players as $pid) {
            update_post_meta($pid, 'current_season_goals', 0);
            update_post_meta($pid, 'current_season_assists', 0);
            update_post_meta($pid, 'current_season_apps', 0);
            $reset_count++;
        }

        // 3. Update Active Season Option
        update_option('fs_active_season_slug', '2026-27');

        $message = '<div class="notice notice-success is-dismissible"><p><strong>Master Reset Complete!</strong> Flushed all transient caches and reset ' . $reset_count . ' player profiles to zero for 2026/27.</p></div>';
    }

    // --- FETCH ALL CLUBS FOR SELECTION ---
    $clubs = get_posts([
        'post_type'      => 'club',
        'posts_per_page' => -1,
        'orderby'        => 'title',
        'order'          => 'ASC'
    ]);

    echo '<div class="wrap" style="font-family: \'Lato\', sans-serif;">';
    echo '<h1 style="font-family: \'Playfair Display\', serif; font-weight: 900; font-size: 32px; margin-bottom: 20px;">Season Rollover & Promotion Manager</h1>';

    echo $message;

    echo '<div style="display: flex; gap: 20px; flex-wrap: wrap; margin-top: 20px;">';

    // TOOL 1: Promotion & Relegation Taxonomy Adjuster
    echo '<div style="flex: 1; min-width: 320px; background: #fff; padding: 25px; border: 2px solid #0A3B25; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.05);">';
    echo '<h2 style="font-family: \'Playfair Display\', serif; font-size: 20px; font-weight: 900; color: #0A3B25; margin-top: 0;">1. Shift Club Division (Promotion / Relegation)</h2>';
    echo '<p style="font-size: 13px; color: #555;">Reassign a club\'s league taxonomy term so they render in the correct 2026/27 division tables.</p>';

    echo '<form method="POST" style="margin-top: 20px;">';
    wp_nonce_field('fs_promo_action');
    echo '<input type="hidden" name="fs_apply_promotions" value="1">';

    echo '<label style="display:block; font-weight:bold; margin-bottom:5px; font-size:12px; text-transform:uppercase;">Select Club:</label>';
    echo '<select name="promo_club_id" style="width:100%; padding:8px; margin-bottom:15px; border-radius:4px;" required>';
    echo '<option value="">-- Choose Club --</option>';

    foreach ($clubs as $c) {
        $terms = wp_get_post_terms($c->ID, 'league', ['fields' => 'slugs']);

        // SILENT FILTER: Skips any club tagged with 'other' or 'international'
        if (in_array('other', $terms) || in_array('international', $terms)) {
            continue;
        }

        $current_term = !empty($terms) ? implode(', ', $terms) : 'Unassigned';
        echo '<option value="' . $c->ID . '">' . esc_html($c->post_title) . ' (' . esc_html($current_term) . ')</option>';
    }

    echo '</select>';

    echo '<label style="display:block; font-weight:bold; margin-bottom:5px; font-size:12px; text-transform:uppercase;">New 2026/27 Division Taxonomy:</label>';
    echo '<select name="target_league_slug" style="width:100%; padding:8px; margin-bottom:20px; border-radius:4px;" required>';
    echo '<option value="thai-league-1">Thai League 1 (T1)</option>';
    echo '<option value="thai-league-2">Thai League 2 (T2)</option>';
    echo '<option value="thai-league-3">Thai League 3 (T3)</option>';
    echo '<option value="tsp">Thailand Semi-Pro League (TSP)</option>';
    echo '</select>';

    echo '<button type="submit" class="button button-primary" style="background:#0A3B25; border-color:#072f1e; font-weight:bold; width:100%; padding:8px 0; text-align:center;">Apply Division Shift</button>';
    echo '</form>';
    echo '</div>';

    // TOOL 2: Master Cache & Stats Reset
    echo '<div style="flex: 1; min-width: 320px; background: #fffcfc; padding: 25px; border: 2px solid #d93025; border-radius: 8px; box-shadow: 0 4px 10px rgba(0,0,0,0.05);">';
    echo '<h2 style="font-family: \'Playfair Display\', serif; font-size: 20px; font-weight: 900; color: #d93025; margin-top: 0;">2. Flush Caches & Reset Player Stats</h2>';
    echo '<p style="font-size: 13px; color: #555;">Wipes all cached frontend transient tables and resets goals, assists, and appearances to 0 across all player posts.</p>';

    echo '<form method="POST" style="margin-top: 40px;">';
    wp_nonce_field('fs_reset_action');
    echo '<input type="hidden" name="fs_run_master_reset" value="1">';
    echo '<button type="submit" class="button button-primary" onclick="return confirm(\'Are you sure you want to flush all caches and zero out player stats for 2026/27?\');" style="background:#d93025; border-color:#b02318; font-weight:bold; width:100%; padding:10px 0; text-align:center;">Execute Master System Reset</button>';
    echo '</form>';
    echo '</div>';

    echo '</div>';
    echo '</div>';
}
